@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Rajdhani:wght@400;500;600;700&family=Share+Tech+Mono&display=swap');

:root {
  --pink: #ff2d95;
  --pink-soft: #ff7ec4;
  --cyan: #22e5ec;
  --purple: #7b2cff;
  --gold: #ffd15c;
  --ink: #0a0612;
  --hud: rgba(10, 6, 18, 0.62);
  --line: rgba(255, 255, 255, 0.14);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%; height: 100%; overflow: hidden; background: #05030a;
  font-family: 'Rajdhani', sans-serif; color: #fff; user-select: none;
  -webkit-font-smoothing: antialiased;
}

#app { position: fixed; inset: 0; overflow: hidden; }
canvas#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.hidden { display: none !important; }

/* ---------------- overlays ---------------- */
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 48%, rgba(4, 2, 10, 0.38) 100%),
    linear-gradient(180deg, rgba(255, 45, 149, 0.055), transparent 18%, transparent 82%, rgba(17, 6, 40, 0.35));
  mix-blend-mode: screen;
}
#vignette::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(2, 0, 8, 0.55) 100%);
  mix-blend-mode: multiply;
}
#damage-flash {
  position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 20, 40, 0.55) 100%);
  transition: opacity 0.12s ease-out;
}

/* ---------------- crosshair ---------------- */
#crosshair { position: absolute; left: 50%; top: 50%; width: 30px; height: 30px; z-index: 4; transform: translate(-50%, -50%); pointer-events: none; opacity: 0.9; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; margin: -1.5px; border-radius: 50%; background: #fff; box-shadow: 0 0 6px rgba(255,255,255,.9); }
.ch-line { position: absolute; background: rgba(255,255,255,.85); box-shadow: 0 0 5px rgba(0,0,0,.7); }
.ch-t, .ch-b { width: 1px; height: 7px; left: 50%; }
.ch-l, .ch-r { height: 1px; width: 7px; top: 50%; }
.ch-t { top: 0; } .ch-b { bottom: 0; } .ch-l { left: 0; } .ch-r { right: 0; }
#crosshair.hit .ch-line { background: var(--pink); box-shadow: 0 0 8px var(--pink); }
body.driving #crosshair { opacity: 0.25; }

/* ---------------- top bar ---------------- */
#topbar { position: absolute; top: 0; left: 0; right: 0; z-index: 5; display: flex; align-items: flex-start; justify-content: space-between; padding: 20px 26px; pointer-events: none; }
#brand { font-family: 'Bebas Neue', sans-serif; font-size: 20px; letter-spacing: 5px; color: rgba(255,255,255,.85); text-shadow: 0 2px 18px rgba(0,0,0,.6); line-height: 1; }
#brand .brand-v { color: var(--pink); font-size: 27px; text-shadow: 0 0 18px var(--pink); margin-right: 1px; }
#brand .brand-2 { color: var(--cyan); text-shadow: 0 0 18px rgba(34,229,236,.65); }
#brand em { display: block; font-style: normal; font-size: 9px; letter-spacing: 7px; color: rgba(255,255,255,.45); margin-top: 5px; margin-left: 2px; }

#mission-chip { text-align: center; padding: 7px 26px 9px; background: linear-gradient(180deg, rgba(10,6,18,.78), rgba(10,6,18,.3)); border: 1px solid rgba(255,255,255,.12); border-top: none; backdrop-filter: blur(7px); border-radius: 0 0 4px 4px; min-width: 250px; }
.chip-label { display: block; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 4px; color: var(--pink-soft); opacity: .85; }
#mission-name { font-size: 17px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; text-shadow: 0 2px 14px rgba(0,0,0,.8); }

#clock { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 2px; text-shadow: 0 2px 14px rgba(0,0,0,.7); }
#time { font-family: 'Share Tech Mono', monospace; font-size: 13px; letter-spacing: 2px; color: rgba(255,255,255,.6); }
#money { font-family: 'Bebas Neue', sans-serif; font-size: 34px; letter-spacing: 1.5px; color: #74ffa9; text-shadow: 0 0 22px rgba(69,255,158,.35); line-height: 1; }
#wanted { display: flex; gap: 3px; height: 20px; align-items: center; margin-bottom: 2px; }
.star { width: 17px; height: 17px; opacity: .17; filter: grayscale(1); transition: all .25s; }
.star.on { opacity: 1; filter: none; animation: starPop .3s cubic-bezier(.2,2,.5,1); }
@keyframes starPop { 0% { transform: scale(.3); } 100% { transform: scale(1); } }

/* ---------------- objective ---------------- */
#objective {
  position: absolute; left: 26px; top: 104px; z-index: 5; width: min(370px, 36vw); pointer-events: none;
  background: linear-gradient(90deg, rgba(10,6,18,.72), rgba(10,6,18,0));
  border-left: 2px solid var(--pink); padding: 9px 16px 12px 14px;
  transition: opacity .4s;
}
.obj-head { display: flex; justify-content: space-between; gap: 10px; font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 2.5px; color: var(--pink-soft); margin-bottom: 4px; }
#objective-timer { color: var(--gold); font-size: 11px; letter-spacing: 1.5px; }
#objective-text { font-size: 14.5px; font-weight: 500; letter-spacing: .4px; line-height: 1.25; color: rgba(255,255,255,.9); text-shadow: 0 2px 10px rgba(0,0,0,.9); }
#objective.urgent { border-left-color: #ff3b30; animation: objPulse .6s infinite alternate; }
@keyframes objPulse { to { background: linear-gradient(90deg, rgba(90,4,16,.75), rgba(10,6,18,0)); } }

/* ---------------- minimap ---------------- */
#minimap-wrap { position: absolute; left: 26px; bottom: 28px; z-index: 5; width: 190px; height: 190px; pointer-events: none; }
#minimap { width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 6px 34px rgba(0,0,0,.65), 0 0 0 1px rgba(255,255,255,.16); background: #07141b; }
.mm-ring { position: absolute; inset: -7px; border-radius: 50%; border: 1px solid rgba(255,255,255,.12); box-shadow: inset 0 0 18px rgba(255,45,149,.14); }
.mm-ring::before, .mm-ring::after { content: ""; position: absolute; background: rgba(255,255,255,.2); }
.mm-ring::before { left: 50%; top: -1px; width: 1px; height: 8px; }
.mm-ring::after { top: 50%; right: -1px; height: 1px; width: 8px; }
.mm-north { position: absolute; top: -18px; left: 50%; transform: translateX(-50%); font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 2px; color: rgba(255,255,255,.5); }
#district { position: absolute; bottom: -4px; left: 50%; transform: translateX(-50%); white-space: nowrap; font-family: 'Share Tech Mono', monospace; font-size: 8.5px; letter-spacing: 3px; color: var(--cyan); text-shadow: 0 0 10px rgba(34,229,236,.5); background: rgba(6,10,16,.75); padding: 2px 8px; border-radius: 2px; }

/* ---------------- status ---------------- */
#status { position: absolute; left: 235px; bottom: 33px; z-index: 5; display: flex; flex-direction: column; gap: 7px; pointer-events: none; }
#health-row, #armor-row { display: flex; align-items: center; gap: 8px; }
.stat-icon { width: 14px; text-align: center; font-size: 11px; color: var(--pink); text-shadow: 0 0 8px var(--pink); }
#armor-row .stat-icon { color: var(--cyan); text-shadow: 0 0 8px var(--cyan); }
.bar { width: 155px; height: 9px; background: rgba(0,0,0,.55); border: 1px solid rgba(255,255,255,.17); transform: skewX(-16deg); overflow: hidden; }
.bar > div { height: 100%; width: 100%; background: linear-gradient(90deg, #ff2d95, #ff7b55); box-shadow: 0 0 12px rgba(255,45,149,.6); transition: width .25s; }
.bar.armor > div { width: 0; background: linear-gradient(90deg, #11b9d6, #63f6ff); box-shadow: 0 0 12px rgba(34,229,236,.5); }
#health-num, #armor-num { font-family: 'Share Tech Mono', monospace; font-size: 10px; color: rgba(255,255,255,.68); width: 24px; }
#health-row.critical .bar > div { animation: hpBlink .5s infinite alternate; }
@keyframes hpBlink { to { background: #ff1f1f; } }

/* ---------------- weapon ---------------- */
#weapon-panel { position: absolute; right: 30px; bottom: 30px; z-index: 5; text-align: right; pointer-events: none; text-shadow: 0 2px 12px rgba(0,0,0,.9); }
.weapon-name { font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 3.5px; color: rgba(255,255,255,.55); margin-bottom: -1px; }
.ammo { font-family: 'Bebas Neue', sans-serif; font-size: 40px; line-height: 1; letter-spacing: 1px; color: #fff; }
.ammo small { font-size: 20px; opacity: .4; margin: 0 4px; }
.ammo span:last-child { font-size: 21px; opacity: .6; }
.ammo.low { color: #ff5050; animation: hpBlink .5s infinite alternate; }

/* ---------------- vehicle hud ---------------- */
#vehicle-hud { position: absolute; right: 28px; bottom: 30px; z-index: 5; width: 170px; text-align: center; pointer-events: none; }
#weapon-panel.hidden + #vehicle-hud { display: block; }
.speedo { position: relative; width: 128px; height: 128px; margin: 0 auto 2px; }
.speedo svg { width: 100%; height: 100%; transform: rotate(135deg); overflow: visible; }
.sp-bg { fill: none; stroke: rgba(255,255,255,.12); stroke-width: 4; stroke-dasharray: 245 327; stroke-linecap: round; }
.sp-fill { fill: none; stroke: var(--pink); stroke-width: 4; stroke-dasharray: 0 327; stroke-linecap: round; filter: drop-shadow(0 0 5px rgba(255,45,149,.8)); transition: stroke-dasharray .08s linear; }
.sp-num { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; font-family: 'Bebas Neue', sans-serif; font-size: 36px; line-height: 1; }
.sp-num small { font-family: 'Share Tech Mono', monospace; font-size: 7.5px; letter-spacing: 2px; opacity: .45; margin-top: 2px; }
#car-name { font-family: 'Bebas Neue', sans-serif; font-size: 18px; letter-spacing: 3px; color: var(--pink-soft); text-shadow: 0 0 14px rgba(255,45,149,.5); }
#radio { font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 1px; color: rgba(255,255,255,.5); margin-top: 3px; }

/* ---------------- prompt ---------------- */
#prompt {
  position: absolute; left: 50%; bottom: 20%; transform: translateX(-50%); z-index: 6;
  display: flex; align-items: center; gap: 10px; padding: 8px 16px 8px 8px;
  background: rgba(8,5,15,.78); border: 1px solid rgba(255,255,255,.18); border-radius: 3px;
  font-size: 13px; letter-spacing: 1px; backdrop-filter: blur(6px); box-shadow: 0 8px 30px rgba(0,0,0,.5);
  animation: promptIn .25s ease-out;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } }
.prompt-key { display: grid; place-items: center; width: 25px; height: 25px; background: #f2f2f2; color: #120a20; font-weight: 700; font-size: 12px; border-radius: 2px; box-shadow: 0 2px 0 #8f8f8f; }

/* ---------------- toasts ---------------- */
#toasts { position: absolute; left: 50%; top: 130px; transform: translateX(-50%); z-index: 8; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none; }
.toast {
  background: linear-gradient(90deg, rgba(10,6,18,.9), rgba(20,10,35,.9)); border: 1px solid rgba(255,255,255,.15);
  border-left: 2px solid var(--cyan); padding: 7px 18px; font-size: 12.5px; letter-spacing: 1.4px; font-weight: 600;
  text-transform: uppercase; box-shadow: 0 6px 26px rgba(0,0,0,.5); animation: toastIn .3s ease-out, toastOut .4s ease-in 2.6s forwards;
  backdrop-filter: blur(8px); white-space: nowrap;
}
.toast.pink { border-left-color: var(--pink); }
.toast.gold { border-left-color: var(--gold); color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* ---------------- banner ---------------- */
#banner { position: absolute; left: 50%; top: 27%; transform: translateX(-50%); z-index: 7; text-align: center; pointer-events: none; animation: bannerIn .5s cubic-bezier(.17,.84,.44,1); }
#banner-kicker { font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 7px; color: var(--pink-soft); margin-bottom: 2px; text-shadow: 0 0 15px rgba(255,45,149,.7); }
#banner-title { font-family: 'Bebas Neue', sans-serif; font-size: clamp(46px, 7vw, 88px); letter-spacing: 5px; line-height: .95; text-shadow: 0 0 45px rgba(255,45,149,.55), 0 5px 30px rgba(0,0,0,.85); }
#banner-sub { font-size: 15px; letter-spacing: 2px; margin-top: 5px; color: rgba(255,255,255,.8); text-shadow: 0 2px 12px #000; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, 18px) scale(.96); filter: blur(6px); } }
#subtitle { position: absolute; left: 50%; bottom: 13%; transform: translateX(-50%); z-index: 7; font-size: 15px; font-style: italic; letter-spacing: .5px; color: #fff; background: rgba(0,0,0,.6); padding: 5px 16px; border-radius: 2px; opacity: 0; transition: opacity .3s; pointer-events: none; text-shadow: 0 2px 6px #000; white-space: nowrap; }
#subtitle.on { opacity: 1; }

/* ---------------- help ---------------- */
#help { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 20; width: min(520px, 92vw); background: rgba(8,5,15,.94); border: 1px solid rgba(255,255,255,.16); border-top: 2px solid var(--cyan); padding: 24px 30px; backdrop-filter: blur(18px); box-shadow: 0 30px 90px rgba(0,0,0,.8); }
#help h2 { font-family: 'Bebas Neue', sans-serif; font-size: 30px; letter-spacing: 6px; color: var(--cyan); margin-bottom: 16px; }
.help-grid { display: grid; grid-template-columns: 100px 1fr; gap: 7px 14px; }
.help-grid span { font-family: 'Share Tech Mono', monospace; font-size: 10.5px; color: var(--gold); letter-spacing: 1px; padding-top: 2px; }
.help-grid p { font-size: 13.5px; color: rgba(255,255,255,.8); letter-spacing: .5px; }
.help-foot { margin-top: 18px; font-size: 11px; color: rgba(255,255,255,.35); font-style: italic; }

/* ---------------- start screen ---------------- */
#start-screen { position: absolute; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center; overflow: hidden; background: #07030f; }
.start-bg { position: absolute; inset: -4%; background:
  radial-gradient(ellipse at 70% 70%, rgba(255,45,149,.35), transparent 45%),
  radial-gradient(ellipse at 25% 30%, rgba(88,32,200,.35), transparent 50%),
  linear-gradient(160deg, #150a2c 0%, #2a0d3d 45%, #6d174e 100%);
  animation: bgShift 12s ease-in-out infinite alternate; }
.start-bg::after { content: ""; position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px); background-size: 100% 4px; opacity: .35; mix-blend-mode: overlay; }
@keyframes bgShift { to { filter: hue-rotate(18deg) saturate(1.15); transform: scale(1.03); } }
.start-inner { position: relative; z-index: 2; text-align: center; display: flex; flex-direction: column; align-items: center; padding: 20px; }
.logo-top { font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 8px; color: rgba(255,255,255,.55); margin-bottom: 8px; }
.logo-top span { opacity: .5; letter-spacing: 3px; }
.logo h1 { font-family: 'Bebas Neue', sans-serif; font-size: clamp(96px, 17vw, 190px); line-height: .72; letter-spacing: 6px; color: #fff; text-shadow: 0 0 18px rgba(255,255,255,.25), 0 0 70px rgba(255,45,149,.5), 0 20px 60px rgba(0,0,0,.5); }
.logo h1 .v { color: var(--pink); text-shadow: 0 0 22px var(--pink), 0 0 80px rgba(255,45,149,.9); display: inline-block; animation: vPulse 3s ease-in-out infinite; }
@keyframes vPulse { 50% { text-shadow: 0 0 35px var(--pink), 0 0 120px rgba(255,45,149,1); } }
.logo-sub { font-family: 'Share Tech Mono', monospace; font-size: clamp(11px, 1.6vw, 17px); letter-spacing: clamp(7px, 1.5vw, 18px); color: var(--cyan); text-shadow: 0 0 20px rgba(34,229,236,.8); margin-top: 12px; }
.start-tag { margin: 26px 0 26px; font-size: 14.5px; line-height: 1.65; color: rgba(255,255,255,.62); letter-spacing: .8px; }
#start-btn { pointer-events: auto; cursor: pointer; border: 1px solid rgba(255,255,255,.35); background: rgba(255,45,149,.12); color: #fff; padding: 13px 44px 11px; display: flex; flex-direction: column; align-items: center; gap: 3px; transition: all .2s; backdrop-filter: blur(6px); clip-path: polygon(10px 0, 100% 0, calc(100% - 10px) 100%, 0 100%); }
#start-btn:hover { background: var(--pink); box-shadow: 0 0 50px rgba(255,45,149,.6); border-color: var(--pink); transform: scale(1.03); }
#start-btn span { font-family: 'Bebas Neue', sans-serif; font-size: 26px; letter-spacing: 5px; }
