import * as THREE from 'three';
import { clamp, damp, dampAngle, rand, randInt, choice, chance, dist, angleDiff } from './utils.js';

const SKINS = [0xc98d6b, 0xe0ab85, 0x8d5c3f, 0xf0c8a0, 0x6b422e, 0xdc9f7a];
const SHIRTS = [0xff7eb6, 0x4fd1c5, 0xffd166, 0xf4f1de, 0x9b5de5, 0xff6b6b, 0x3a86ff, 0xf2a65a, 0xb8f2e6];
const PANTS = [0x2b2d42, 0x5c4d3c, 0x1b263b, 0xd8d8d8, 0x3d405b, 0x242423];

function mat(color, rough = 0.8, metal = 0.05) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal });
}

export function createHuman({ shirt, pants, skin, hair = 0x201812, shades = false, cap = null, shoes = 0x1a1a1a, tie = null } = {}) {
  shirt = shirt ?? choice(SHIRTS);
  pants = pants ?? choice(PANTS);
  skin = skin ?? choice(SKINS);

  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);

  const skinMat = mat(skin, 0.75);
  const shirtMat = mat(shirt, 0.78);
  const pantsMat = mat(pants, 0.85);
  const shoeMat = mat(shoes, 0.5, 0.1);

  // hips & torso
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.26, 0.44, 4, 10), shirtMat);
  torso.position.y = 1.19;
  torso.scale.set(1.08, 1, 0.72);
  torso.castShadow = true;
  body.add(torso);
  const belly = new THREE.Mesh(new THREE.CapsuleGeometry(0.23, 0.16, 4, 10), shirtMat);
  belly.position.y = 0.96;
  belly.scale.set(1.05, 1, 0.75);
  body.add(belly);

  // neck + head
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.13, 8), skinMat);
  neck.position.y = 1.52;
  body.add(neck);
  const head = new THREE.Group();
  head.position.y = 1.65;
  body.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.185, 14, 12), skinMat);
  skull.scale.set(0.9, 1.08, 0.95);
  skull.castShadow = true;
  head.add(skull);
  // nose
  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.038, 0.1, 5), skinMat);
  nose.rotation.x = Math.PI / 2;
  nose.position.set(0, -0.01, 0.18);
  head.add(nose);
  // hair
  const hairMat = mat(hair, 0.95);
  const hairCap = new THREE.Mesh(new THREE.SphereGeometry(0.192, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.58), hairMat);
  hairCap.position.y = 0.015;
  hairCap.scale.set(0.93, 1.06, 0.98);
  head.add(hairCap);
  if (cap) {
    const capMat = mat(cap, 0.8);
    const dome = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.5), capMat);
    dome.position.y = 0.055; head.add(dome);
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.035, 0.19), capMat);
    brim.position.set(0, 0.06, 0.17); head.add(brim);
  }
  if (shades) {
    const glass = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.075, 0.04), new THREE.MeshStandardMaterial({ color: 0x0b0b12, metalness: 0.7, roughness: 0.15 }));
    glass.position.set(0, 0.035, 0.175);
    head.add(glass);
    const bridge = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.02, 0.03), mat(0x0b0b12, 0.2, 0.8));
    bridge.position.set(0, 0.07, 0.18); head.add(bridge);
  }
  if (tie) {
    const t = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.32, 0.03), mat(tie, 0.5));
    t.position.set(0, 1.22, 0.19); body.add(t);
  }

  // arms
  const armL = new THREE.Group();
  armL.position.set(-0.34, 1.4, 0);
  body.add(armL);
  const upperL = new THREE.Mesh(new THREE.CapsuleGeometry(0.072, 0.34, 3, 8), shirtMat);
  upperL.position.y = -0.2; upperL.castShadow = true; armL.add(upperL);
  const handL = new THREE.Mesh(new THREE.SphereGeometry(0.075, 8, 6), skinMat);
  handL.position.y = -0.44; armL.add(handL);

  const armR = new THREE.Group();
  armR.position.set(0.34, 1.4, 0);
  body.add(armR);
  const upperR = new THREE.Mesh(new THREE.CapsuleGeometry(0.072, 0.34, 3, 8), shirtMat);
  upperR.position.y = -0.2; upperR.castShadow = true; armR.add(upperR);
  const handR = new THREE.Mesh(new THREE.SphereGeometry(0.075, 8, 6), skinMat);
  handR.position.y = -0.44; armR.add(handR);

  // legs
  const legL = new THREE.Group();
  legL.position.set(-0.14, 0.92, 0);
  body.add(legL);
  const thighL = new THREE.Mesh(new THREE.CapsuleGeometry(0.098, 0.55, 3, 8), pantsMat);
  thighL.position.y = -0.34; thighL.castShadow = true; legL.add(thighL);
  const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.3), shoeMat);
  shoeL.position.set(0, -0.88, 0.05); legL.add(shoeL);

  const legR = new THREE.Group();
  legR.position.set(0.14, 0.92, 0);
  body.add(legR);
  const thighR = new THREE.Mesh(new THREE.CapsuleGeometry(0.098, 0.55, 3, 8), pantsMat);
  thighR.position.y = -0.34; thighR.castShadow = true; legR.add(thighR);
  const shoeR = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.3), shoeMat);
  shoeR.position.set(0, -0.88, 0.05); legR.add(shoeR);

  const allMeshes = [];
  group.traverse(o => { if (o.isMesh) { o.userData.human = group; allMeshes.push(o); } });

  return { group, body, head, armL, armR, legL, legR, torso, allMeshes, handR };
}

export function animateHuman(h, t, speed, opts = {}) {
  const moving = speed > 0.25;
  const amp = clamp(speed / 7, 0, 1.2);
  const cycle = t * (4.2 + speed * 0.85);
  if (opts.aim) {
    h.armR.rotation.x = damp(h.armR.rotation.x, -1.45, 12, 0.016);
    h.armR.rotation.z = damp(h.armR.rotation.z, 0.12, 12, 0.016);
    h.armL.rotation.x = damp(h.armL.rotation.x, -0.3, 10, 0.016);
  } else if (moving) {
    h.armL.rotation.x = damp(h.armL.rotation.x, Math.sin(cycle) * 0.75 * amp, 14, 0.016);
    h.armR.rotation.x = damp(h.armR.rotation.x, -Math.sin(cycle) * 0.75 * amp, 14, 0.016);
  } else {
    h.armL.rotation.x = damp(h.armL.rotation.x, Math.sin(t * 1.6) * 0.05, 4, 0.016);
    h.armR.rotation.x = damp(h.armR.rotation.x, -Math.sin(t * 1.6) * 0.05, 4, 0.016);
  }
  h.armL.rotation.z = damp(h.armL.rotation.z, 0.07, 6, 0.016);
  h.armR.rotation.z = damp(h.armR.rotation.z, -0.07, 6, 0.016);
  if (moving) {
    h.legL.rotation.x = Math.sin(cycle) * 0.68 * amp;
    h.legR.rotation.x = -Math.sin(cycle) * 0.68 * amp;
    h.body.position.y = Math.abs(Math.sin(cycle)) * 0.045 * amp;
  } else {
    h.legL.rotation.x = damp(h.legL.rotation.x, 0, 8, 0.016);
    h.legR.rotation.x = damp(h.legR.rotation.x, 0, 8, 0.016);
    h.body.position.y = damp(h.body.position.y, 0, 8, 0.016);
  }
  h.body.rotation.z = damp(h.body.rotation.z, moving ? Math.sin(cycle) * 0.025 : 0, 8, 0.016);
}

/* ============================================================ */
export class Player {
  constructor(game) {
    this.game = game;
    this.mesh = createHuman({
      shirt: 0xf2ede2, pants: 0xf1ead9, skin: 0xd9a077, hair: 0x1b1410,
      shades: true, shoes: 0x2b2118, tie: 0x1b1a24,
    });
    this.group = this.mesh.group;
    this.position = new THREE.Vector3(226, 0.14, 142);
    this.velocity = new THREE.Vector3();
    this.heading = Math.PI;
    this.vy = 0;
    this.onGround = true;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 0;
    this.maxArmor = 100;
    this.radius = 0.42;
    this.inVehicle = null;
    this.weapon = { name: 'PISTOL', mag: 12, reserve: 60, maxMag: 12, damage: 28, rpm: 320, auto: false };
    this.reloading = 0;
    this.fireCooldown = 0;
    this.speed = 0;
    this.aimTimer = 0;
    this.dead = false;
    this.shootAnim = 0;
    this.stepOffset = 0;
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    game.scene.add(this.group);
  }

  get pos() { return this.position; }

  reset(pos) {
    this.position.set(pos.x, this.game.city.groundHeight(pos.x, pos.z), pos.z);
    this.velocity.set(0, 0, 0);
    this.health = 100; this.armor = 0; this.dead = false;
    this.mesh.group.rotation.set(0, 0, 0);
    this.mesh.body.rotation.set(0, 0, 0);
    this.mesh.body.position.y = 0;
    this.mesh.group.visible = true;
  }

  update(dt) {
    if (this.dead) return;
    if (this.inVehicle) { this.updateInVehicle(dt); return; }
    const inp = this.game.input;
    const camYaw = this.game.cameraYaw;

    let fwd = 0, strafe = 0;
    if (inp.isDown('KeyW') || inp.isDown('ArrowUp')) fwd += 1;
    if (inp.isDown('KeyS') || inp.isDown('ArrowDown')) fwd -= 1;
    if (inp.isDown('KeyD') || inp.isDown('ArrowRight')) strafe += 1;
    if (inp.isDown('KeyA') || inp.isDown('ArrowLeft')) strafe -= 1;

    const sprint = inp.isDown('ShiftLeft') || inp.isDown('ShiftRight');
    const targetSpeed = sprint ? 9.4 : 5.4;
    const dir = new THREE.Vector3(
      -Math.sin(camYaw) * fwd + Math.cos(camYaw) * strafe, 0,
      -Math.cos(camYaw) * fwd - Math.sin(camYaw) * strafe,
    );
    const moving = dir.lengthSq() > 0.01;
    if (moving) dir.normalize();
    const desired = moving ? dir.multiplyScalar(targetSpeed) : new THREE.Vector3();
    this.velocity.x = damp(this.velocity.x, desired.x, moving ? 12 : 14, dt);
    this.velocity.z = damp(this.velocity.z, desired.z, moving ? 12 : 14, dt);
    this.speed = Math.hypot(this.velocity.x, this.velocity.z);

    if (moving && this.speed > 0.3) {
      const targetHeading = Math.atan2(this.velocity.x, this.velocity.z);
      this.heading = dampAngle(this.heading, targetHeading, 14, dt);
    }

    // jump / gravity
    if (inp.consume('Space') && this.onGround) {
      this.vy = 6.2;
      this.onGround = false;
      this.game.audio?.jump();
    }
    this.vy -= 20 * dt;
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    this.position.y += this.vy * dt;

    this.game.city.collide(this.position, this.radius);
    const ground = this.game.city.groundHeight(this.position.x, this.position.z);
    if (this.position.y <= ground) {
      this.position.y = ground;
      this.vy = 0;
      this.onGround = true;
    }

    // moving vehicle push
    for (const v of this.game.vehicles) {
      if (v === this.inVehicle || v.destroyed) continue;
      const d = Math.hypot(v.position.x - this.position.x, v.position.z - this.position.z);
      if (d < 2.1 && Math.abs(v.speed) > 3) {
        const push = new THREE.Vector3(this.position.x - v.position.x, 0, this.position.z - v.position.z).normalize();
        this.position.x += push.x * 0.6;
        this.position.z += push.z * 0.6;
        this.game.damagePlayer(Math.abs(v.speed) * 1.1, v.position, 'traffic');
        this.vy = 3.5;
      }
    }

    // animation
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    const aim = inp.mouseDown && this.fireCooldown > 0;
    animateHuman(this.mesh, this.game.elapsed, this.speed, { aim: this.aimTimer > 0.15 });
    if (this.aimTimer > 0) this.aimTimer -= dt;

    // walk dust
    if (this.speed > 3 && this.onGround) {
      this.stepOffset -= this.speed * dt;
      if (this.stepOffset < 0) {
        this.stepOffset = 2.4;
        this.game.effects?.dust(this.position, 0.5);
      }
    }

    // out of world safety
    if (this.position.y < -6) this.reset({ x: 226, z: 142 });
  }

  updateInVehicle(dt) {
    const v = this.inVehicle;
    this.position.copy(v.position);
    this.position.y = v.position.y;
    this.group.visible = false;
    this.speed = Math.abs(v.speed);
    if (this.game.input.consume('KeyE')) {
      this.exitVehicle();
    }
  }

  enterVehicle(v) {
    if (!v || v.destroyed) return;
    this.inVehicle = v;
    v.driver = 'player';
    v.ai = null;
    v.speed = Math.max(v.speed, 0);
    this.group.visible = false;
    this.game.playerEnteredVehicle(v);
  }

  exitVehicle() {
    const v = this.inVehicle;
    if (!v) return;
    const side = new THREE.Vector3(Math.cos(v.heading), 0, -Math.sin(v.heading)).multiplyScalar(2.1);
    this.position.set(v.position.x + side.x, v.position.y + 0.6, v.position.z + side.z);
    this.game.city.collide(this.position, this.radius);
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    this.inVehicle = null;
    this.group.visible = true;
    this.velocity.set(0, 0, 0);
    this.heading = v.heading;
    v.driver = null;
    v.speed *= 0.2;
    this.game.playerExitedVehicle(v);
  }

  takeDamage(amount, from, source = 'unknown') {
    if (this.dead) return;
    let dmg = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.65);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.health = Math.max(0, this.health - dmg);
    this.game.onPlayerDamaged?.(source, from);
    this.game.audio?.hurt();
    if (this.health <= 0) this.die();
  }

  die() {
    this.dead = true;
    this.mesh.body.rotation.z = Math.PI / 2;
    this.mesh.body.position.y = 0.2;
    this.game.onPlayerDeath?.();
  }

  respawn() {
    this.reset({ x: 226, z: 142 });
    this.health = 100;
    this.armor = 0;
    this.mesh.group.rotation.set(0, this.heading, 0);
    this.mesh.body.rotation.set(0, 0, 0);
    this.mesh.body.position.y = 0;
    this.group.visible = true;
  }
}

/* ============================================================ */
export class Ped {
  constructor(game, pos) {
    this.game = game;
    this.mesh = createHuman({
      shirt: choice(SHIRTS), pants: choice(PANTS), skin: choice(SKINS),
      hair: choice([0x1b1410, 0x3d2b1f, 0x101010, 0x6b4b2a, 0xc9a56a]),
      shades: chance(0.2), cap: chance(0.18) ? choice([0xff2d95, 0x22e5ec, 0x222222, 0xffd15c]) : null,
    });
    this.group = this.mesh.group;
    this.position = new THREE.Vector3(pos.x, game.city.groundHeight(pos.x, pos.z), pos.z);
    this.heading = rand(0, Math.PI * 2);
    this.speed = rand(1.1, 1.8);
    this.baseSpeed = this.speed;
    this.state = 'walk';
    this.fleeTimer = 0;
    this.target = this.pickTarget();
    this.dead = false;
    this.health = 24;
    this.radius = 0.4;
    this.animT = rand(0, 10);
    this.fall = 0;
    this.deathTimer = 0;
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    game.scene.add(this.group);
  }

  pickTarget() {
    const c = this.game.city;
    // choose a point on sidewalk near current location or beach promenade
    if (chance(0.3)) return { x: rand(212, 234), z: clamp(this.position.z + rand(-40, 40), -225, 225) };
    const block = choice(c.blocks);
    const side = randInt(0, 3);
    let x, z;
    if (side === 0) { x = block.cx + rand(-38, 38); z = block.cz - 38; }
    else if (side === 1) { x = block.cx + rand(-38, 38); z = block.cz + 38; }
    else if (side === 2) { x = block.cx - 38; z = block.cz + rand(-38, 38); }
    else { x = block.cx + 38; z = block.cz + rand(-38, 38); }
    return { x, z };
  }

  alert(origin) {
    if (this.dead) return;
    const d = dist(this.position, origin);
    if (d < 45) {
      this.state = 'flee';
      this.fleeTimer = rand(4, 9);
      this.speed = rand(4.5, 6.5);
      // run away from origin
      const dx = this.position.x - origin.x, dz = this.position.z - origin.z;
      const l = Math.hypot(dx, dz) || 1;
      this.target = { x: clamp(this.position.x + dx / l * 30, -230, 230), z: clamp(this.position.z + dz / l * 30, -230, 230) };
    }
  }

  hit(damage, from) {
    if (this.dead) return;
    this.health -= damage;
    this.game.effects?.blood(this.position);
    this.game.audio?.impact();
    this.alert(from || this.position);
    if (this.health <= 0) this.kill();
  }

  kill() {
    this.dead = true;
    this.state = 'dead';
    this.game.onPedKilled?.(this);
    this.game.effects?.blood(this.position, 2.2);
  }

  update(dt, playerPos) {
    if (this.dead) {
      this.deathTimer += dt;
      this.fall = Math.min(1, this.fall + dt * 3.2);
      this.mesh.body.rotation.x = -this.fall * Math.PI * 0.48;
      this.mesh.body.position.y = 0.12;
      return;
    }
    if (this.fleeTimer > 0) {
      this.fleeTimer -= dt;
      if (this.fleeTimer <= 0) { this.state = 'walk'; this.speed = this.baseSpeed; this.target = this.pickTarget(); }
    }
    if (this.state === 'flee' && this.fleeTimer > 0 && chance(dt * 0.8)) this.target = this.pickTarget();

    const dx = this.target.x - this.position.x;
    const dz = this.target.z - this.position.z;
    const d = Math.hypot(dx, dz);
    if (d < 1.5) {
      this.target = this.pickTarget();
    } else {
      const hx = dx / d, hz = dz / d;
      this.position.x += hx * this.speed * dt;
      this.position.z += hz * this.speed * dt;
      const targetHeading = Math.atan2(hx, hz);
      this.heading = dampAngle(this.heading, targetHeading, 5, dt);
    }
    this.game.city.collide(this.position, this.radius);
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    this.animT += dt;
    animateHuman(this.mesh, this.animT, this.speed, {});

    // simple separation from player
    const pd = dist(this.position, playerPos);
    if (pd < 1.1) {
      const l = Math.max(0.01, pd);
      this.position.x += (this.position.x - playerPos.x) / l * 0.4;
      this.position.z += (this.position.z - playerPos.z) / l * 0.4;
    }

    // distance culling respawn
    if (dist(this.position, playerPos) > 190) {
      const ang = rand(0, Math.PI * 2), r = rand(80, 130);
      this.position.set(clamp(playerPos.x + Math.cos(ang) * r, -220, 285), 0, clamp(playerPos.z + Math.sin(ang) * r, -220, 220));
      this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
      this.target = this.pickTarget();
    }
  }
}

/* ============================================================ */
export class Enemy {
  constructor(game, pos, opts = {}) {
    this.game = game;
    this.mesh = createHuman({
      shirt: opts.shirt ?? choice([0x9b1b30, 0x2b2b2b, 0x3a2b52, 0x1e4d3a]),
      pants: 0x1b1b24, skin: choice(SKINS), hair: 0x120e0a,
      shades: true,
    });
    this.group = this.mesh.group;
    this.position = new THREE.Vector3(pos.x, game.city.groundHeight(pos.x, pos.z), pos.z);
    this.heading = opts.heading ?? rand(0, Math.PI * 2);
    this.health = opts.health ?? 62;
    this.maxHealth = this.health;
    this.speed = 0;
    this.dead = false;
    this.fall = 0;
    this.deathTimer = 0;
    this.fireTimer = rand(0.8, 2.0);
    this.radius = 0.42;
    this.animT = rand(0, 5);
    this.aiming = false;
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    game.scene.add(this.group);
  }

  hit(damage, from) {
    if (this.dead) return false;
    this.health -= damage;
    this.game.effects?.blood(this.position);
    this.game.audio?.impact();
    this.game.hitMarker?.();
    if (this.health <= 0) {
      this.dead = true;
      this.game.effects?.blood(this.position, 2.5);
      this.game.onEnemyKilled?.(this);
    }
    return true;
  }

  update(dt, playerPos) {
    if (this.dead) {
      this.deathTimer += dt;
      this.fall = Math.min(1, this.fall + dt * 3.5);
      this.mesh.body.rotation.x = -this.fall * Math.PI * 0.5;
      this.mesh.body.position.y = 0.1;
      return;
    }
    const dx = playerPos.x - this.position.x;
    const dz = playerPos.z - this.position.z;
    const d = Math.hypot(dx, dz);
    const ang = Math.atan2(dx, dz);
    this.heading = dampAngle(this.heading, ang, 6, dt);
    this.aiming = d < 45;

    if (d > 17) {
      const sp = d > 42 ? 3.8 : 2.2;
      this.position.x += (dx / (d || 1)) * sp * dt;
      this.position.z += (dz / (d || 1)) * sp * dt;
      this.speed = sp;
    } else {
      this.speed = 0;
      // strafe slightly
      this.position.x += Math.cos(ang) * 0.7 * dt * Math.sin(this.animT);
      this.position.z += -Math.sin(ang) * 0.7 * dt * Math.sin(this.animT);
    }
    this.game.city.collide(this.position, this.radius);
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    this.animT += dt;
    animateHuman(this.mesh, this.animT, this.speed, { aim: this.aiming });

    if (!this.game.player.dead && d < 40 && this.game.hasLineOfSight?.(this.position, playerPos)) {
      this.fireTimer -= dt;
      if (this.fireTimer <= 0) {
        this.fireTimer = rand(1.1, 2.2);
        this.game.enemyShoot(this, playerPos);
      }
    } else {
      this.fireTimer = Math.max(this.fireTimer, 0.7);
    }
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import { CITY, clamp, damp, dampAngle, rand, randInt, choice, chance, dist, angleDiff, glowTexture } from './utils.js';

const CAR_TYPES = {
  stinger: { name: 'STINGER', length: 4.5, width: 1.98, bodyH: 0.42, cabinH: 0.46, cabinL: 1.9, maxSpeed: 42, accel: 16, color: 0xffd15c, sports: true },
  infernus: { name: 'INFERNUS', length: 4.55, width: 2.05, bodyH: 0.38, cabinH: 0.42, cabinL: 1.7, maxSpeed: 48, accel: 19, color: 0xff2d95, sports: true },
  cheetah: { name: 'CHEETAH', length: 4.6, width: 2.0, bodyH: 0.4, cabinH: 0.44, cabinL: 1.85, maxSpeed: 46, accel: 18, color: 0xffffff, sports: true },
  sedan: { name: 'OCEANIC', length: 4.4, width: 1.92, bodyH: 0.6, cabinH: 0.66, cabinL: 2.2, maxSpeed: 25, accel: 9, color: 0x3d8bd4 },
  taxi: { name: 'CABBIE', length: 4.4, width: 1.92, bodyH: 0.6, cabinH: 0.68, cabinL: 2.25, maxSpeed: 26, accel: 10, color: 0xffcf2e },
  van: { name: 'RUMPO', length: 5.2, width: 2.1, bodyH: 1.0, cabinH: 0.8, cabinL: 2.8, maxSpeed: 21, accel: 7, color: 0xe8e3d8 },
  pickup: { name: 'BOBCAT', length: 4.9, width: 2.0, bodyH: 0.62, cabinH: 0.62, cabinL: 1.8, maxSpeed: 26, accel: 10, color: 0x8c3e2e },
  police: { name: 'POLICE CRUISER', length: 4.5, width: 1.98, bodyH: 0.6, cabinH: 0.66, cabinL: 2.2, maxSpeed: 36, accel: 15, color: 0x101018, police: true },
};

const TRAFFIC_TYPES = ['sedan', 'sedan', 'taxi', 'van', 'pickup', 'stinger'];

export function createCarModel(typeKey, colorOverride) {
  const spec = CAR_TYPES[typeKey] || CAR_TYPES.sedan;
  const color = colorOverride ?? spec.color;
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({ color, metalness: 0.45, roughness: 0.32 });
  const trimMat = new THREE.MeshStandardMaterial({ color: 0x15151b, metalness: 0.6, roughness: 0.4 });
  const glassMat = new THREE.MeshStandardMaterial({ color: 0x0a1420, metalness: 0.9, roughness: 0.08, transparent: true, opacity: 0.92 });
  const chromeMat = new THREE.MeshStandardMaterial({ color: 0xdfe6ea, metalness: 1, roughness: 0.15 });
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x0b0b0e, roughness: 0.9 });
  const hubMat = new THREE.MeshStandardMaterial({ color: 0xb9c2c8, metalness: 0.9, roughness: 0.25 });

  const L = spec.length, W = spec.width;
  const bodyY = spec.sports ? 0.52 : 0.62;
  const body = new THREE.Mesh(new RoundedBoxGeometry(W, spec.bodyH, L, 3, 0.18), bodyMat);
  body.position.y = bodyY;
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  // lower skirt / bumpers
  const skirt = new THREE.Mesh(new RoundedBoxGeometry(W + 0.04, 0.22, L * 0.98, 2, 0.08), trimMat);
  skirt.position.y = bodyY - spec.bodyH / 2 + 0.06;
  group.add(skirt);

  if (typeKey === 'van') {
    const cargo = new THREE.Mesh(new RoundedBoxGeometry(W - 0.08, 1.15, L * 0.62, 3, 0.12), bodyMat);
    cargo.position.set(0, bodyY + 0.55, -L * 0.16);
    cargo.castShadow = true;
    group.add(cargo);
  }

  // cabin
  const cabin = new THREE.Mesh(new RoundedBoxGeometry(W * 0.86, spec.cabinH, spec.cabinL, 3, 0.16), glassMat);
  cabin.position.set(0, bodyY + spec.bodyH / 2 + spec.cabinH / 2 - 0.04, spec.sports ? -0.3 : -0.1);
  cabin.castShadow = true;
  group.add(cabin);
  // roof
  const roof = new THREE.Mesh(new RoundedBoxGeometry(W * 0.8, 0.1, spec.cabinL * 0.9, 2, 0.05), bodyMat);
  roof.position.set(0, cabin.position.y + spec.cabinH / 2 + 0.02, cabin.position.z);
  group.add(roof);
  // pillars
  for (const sx of [-1, 1]) {
    const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.07, spec.cabinH, 0.1), bodyMat);
    pillar.position.set(sx * W * 0.42, cabin.position.y, cabin.position.z + spec.cabinL * 0.45);
    group.add(pillar);
  }

  // lights
  const headMat = new THREE.MeshBasicMaterial({ color: 0xfff2c4, toneMapped: false });
  const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2233, toneMapped: false });
  const headGeo = new THREE.BoxGeometry(0.4, 0.15, 0.08);
  const tailGeo = new THREE.BoxGeometry(0.45, 0.13, 0.07);
  for (const sx of [-1, 1]) {
    const h = new THREE.Mesh(headGeo, headMat);
    h.position.set(sx * W * 0.31, bodyY + 0.06, L / 2 + 0.01);
    group.add(h);
    const t = new THREE.Mesh(tailGeo, tailMat);
    t.position.set(sx * W * 0.32, bodyY + 0.08, -L / 2 - 0.01);
    group.add(t);
  }
  // grille
  const grille = new THREE.Mesh(new THREE.BoxGeometry(W * 0.5, 0.16, 0.06), chromeMat);
  grille.position.set(0, bodyY - 0.1, L / 2 + 0.02);
  group.add(grille);

  // wheels
  const wheels = [];
  const wheelGroups = [];
  const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.26, 14);
  wheelGeo.rotateZ(Math.PI / 2);
  const hubGeo = new THREE.CylinderGeometry(0.17, 0.17, 0.28, 8);
  hubGeo.rotateZ(Math.PI / 2);
  const axleZ = spec.sports ? L * 0.31 : L * 0.32;
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const wg = new THREE.Group();
      wg.position.set(sx * (W / 2 - 0.06), 0.36, sz * axleZ);
      const tire = new THREE.Mesh(wheelGeo, tireMat);
      tire.castShadow = true;
      wg.add(tire);
      const hub = new THREE.Mesh(hubGeo, hubMat);
      wg.add(hub);
      group.add(wg);
      wheels.push(tire);
      wheelGroups.push({ group: wg, front: sz > 0, sx });
    }
  }

  // taxi sign / police kit
  if (typeKey === 'taxi') {
    const signMat = new THREE.MeshBasicMaterial({ color: 0xfff0a0, toneMapped: false });
    const sign = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.28, 0.32), signMat);
    sign.position.set(0, roof.position.y + 0.2, cabin.position.z);
    group.add(sign);
  }
  if (typeKey === 'police') {
    const white = new THREE.MeshStandardMaterial({ color: 0xe8e8f0, roughness: 0.4, metalness: 0.2 });
    for (const sx of [-1, 1]) {
      const door = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.42, 1.5), white);
      door.position.set(sx * (W / 2 + 0.005), bodyY + 0.02, 0.1);
      group.add(door);
    }
    const bar = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.14, 0.34), trimMat);
    bar.position.set(0, roof.position.y + 0.12, cabin.position.z);
    group.add(bar);
    const red = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.32), new THREE.MeshBasicMaterial({ color: 0xff1a2e, toneMapped: false }));
    red.position.set(-0.27, bar.position.y + 0.13, bar.position.z);
    group.add(red);
    const blue = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.32), new THREE.MeshBasicMaterial({ color: 0x1a6dff, toneMapped: false }));
    blue.position.set(0.27, bar.position.y + 0.13, bar.position.z);
    group.add(blue);
    group.userData.policeLights = { red, blue };
    // push bar
    const bull = new THREE.Mesh(new THREE.BoxGeometry(W * 0.8, 0.35, 0.12), trimMat);
    bull.position.set(0, bodyY - 0.05, L / 2 + 0.12);
    group.add(bull);
  }

  // driver silhouette (hidden for player)
  const driver = new THREE.Group();
  const dHead = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 8), new THREE.MeshStandardMaterial({ color: 0x8a5c3e, roughness: 0.8 }));
  dHead.position.y = 1.42;
  const dBody = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.24, 0.45, 8), new THREE.MeshStandardMaterial({ color: 0x2a2a35, roughness: 0.9 }));
  dBody.position.y = 1.1;
  driver.add(dHead, dBody);
  driver.position.z = -0.1;
  group.add(driver);

  // underglow for sports
  if (spec.sports) {
    const glow = new THREE.Mesh(new THREE.PlaneGeometry(W * 1.9, L * 1.05), new THREE.MeshBasicMaterial({ map: glowTexture('#ff2d95', 0.08), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.5 }));
    glow.rotation.x = -Math.PI / 2;
    glow.position.y = 0.07;
    group.add(glow);
    group.userData.underglow = glow;
  }

  group.userData.body = body;
  group.userData.driver = driver;
  group.userData.spec = spec;
  return { group, wheels, wheelGroups, driver, spec, bodyMat, headlights: headMat, taillights: tailMat };
}

/* ============================================================ */
export class Vehicle {
  constructor(game, type = 'sedan', pos = { x: 0, z: 0 }, heading = 0, color) {
    this.game = game;
    this.type = type;
    this.spec = CAR_TYPES[type] || CAR_TYPES.sedan;
    this.name = this.spec.name;
    this.model = createCarModel(type, color);
    this.group = this.model.group;
    this.position = new THREE.Vector3(pos.x, game.city.groundHeight(pos.x, pos.z), pos.z);
    this.heading = heading;
    this.speed = 0;
    this.steer = 0;
    this.driver = null; // 'player' | 'ai' | 'police' | null
    this.ai = null;
    this.health = 100;
    this.maxHealth = 100;
    this.radius = 1.55;
    this.destroyed = false;
    this.burnTimer = 0;
    this.collisionCooldown = 0;
    this.wheelSpin = 0;
    this.bodyTilt = 0;
    this.lastX = pos.x; this.lastZ = pos.z;
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    this.id = Math.random().toString(36).slice(2);
    game.scene.add(this.group);
  }

  get forward() { return new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading)); }

  setTrafficRoute() {
    // choose a road & direction
    const axis = chance(0.5) ? 'x' : 'z';
    const road = choice(CITY.roads);
    const dir = chance(0.5) ? 1 : -1;
    if (axis === 'x') {
      this.position.x = clamp(this.position.x, -190, 190);
      this.position.z = road + (dir > 0 ? -4.2 : 4.2);
      this.heading = dir > 0 ? Math.PI / 2 : -Math.PI / 2;
    } else {
      this.position.z = clamp(this.position.z, -190, 190);
      this.position.x = road + (dir > 0 ? 4.2 : -4.2);
      this.heading = dir > 0 ? 0 : Math.PI;
    }
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    const ni = CITY.roads.reduce((best, r, i) => Math.abs(r - (axis === 'x' ? this.position.x : this.position.z)) < Math.abs(CITY.roads[best] - (axis === 'x' ? this.position.x : this.position.z)) ? i : best, 0);
    const step = 1;
    const nextI = clamp(ni + dir * step, 0, CITY.roads.length - 1);
    this.ai = { kind: 'traffic', axis, dir, ni, nextI, cruise: rand(8, 14), stopped: 0, wobble: rand(0, 6) };
    this.targetPoint = this.computeAiTarget();
    this.applyTransform();
  }

  computeAiTarget() {
    const ai = this.ai;
    const road = CITY.roads[ai.ni];
    const nextRoad = CITY.roads[ai.nextI];
    if (ai.axis === 'x') {
      return new THREE.Vector3(nextRoad, 0, road + (ai.dir > 0 ? -4.2 : 4.2));
    }
    return new THREE.Vector3(road + (ai.dir > 0 ? 4.2 : -4.2), 0, nextRoad);
  }

  chooseNextNode() {
    const ai = this.ai;
    ai.ni = ai.nextI;
    // turn options
    const options = [];
    if (ai.nextI + 1 < CITY.roads.length) options.push({ axis: ai.axis, dir: 1, ni: ai.nextI, nextI: ai.nextI + 1 });
    if (ai.nextI - 1 >= 0) options.push({ axis: ai.axis, dir: -1, ni: ai.nextI, nextI: ai.nextI - 1 });
    const perpAxis = ai.axis === 'x' ? 'z' : 'x';
    const currentCoord = CITY.roads[ai.nextI];
    const gridIndex = ai.nextI;
    if (gridIndex + 1 < CITY.roads.length) options.push({ axis: perpAxis, dir: 1, ni: gridIndex, nextI: gridIndex + 1, intersect: true });
    if (gridIndex - 1 >= 0) options.push({ axis: perpAxis, dir: -1, ni: gridIndex, nextI: gridIndex - 1, intersect: true });
    // prefer straight
    const straight = options.filter(o => o.axis === ai.axis && o.dir === ai.dir);
    const pick = straight.length && chance(0.62) ? straight[0] : choice(options);
    // current coordinate along new travel axis
    if (pick.axis === 'x') {
      // we are at intersection (CITY.roads[nextI], CITY.roads[gridIndex]) -> need appropriate ni for z road
      const zIndex = ai.ni; // after turn, road coordinate is intersection's other axis
      ai.axis = 'x';
      ai.ni = zIndex;
      ai.dir = pick.dir;
      ai.nextI = clamp(zIndex + pick.dir, 0, CITY.roads.length - 1);
    } else {
      const xIndex = ai.ni;
      ai.axis = 'z';
      ai.ni = xIndex;
      ai.dir = pick.dir;
      ai.nextI = clamp(xIndex + pick.dir, 0, CITY.roads.length - 1);
    }
    this.targetPoint = this.computeAiTarget();
  }

  applyTransform() {
    this.group.position.copy(this.position);
    this.group.rotation.y = this.heading;
    this.group.rotation.z = this.bodyTilt;
  }

  update(dt, elapsed) {
    if (this.destroyed) {
      this.burnTimer += dt;
      this.group.position.y = this.position.y;
      return;
    }
    this.collisionCooldown = Math.max(0, this.collisionCooldown - dt);
    if (this.driver === 'player') this.updatePlayer(dt);
    else if (this.driver === 'police') this.updatePolice(dt);
    else if (this.driver === 'ai') this.updateTraffic(dt);
    else this.updateParked(dt);

    // wheel visuals
    this.wheelSpin += this.speed * dt / 0.36;
    for (const w of this.model.wheelGroups) {
      w.group.rotation.x = this.wheelSpin;
      if (w.front) w.group.rotation.y = this.steer * 0.5;
    }
    if (this.model.driver) this.model.driver.visible = !this.driver;
    this.applyTransform();

    // police lights
    if (this.group.userData.policeLights) {
      const p = this.group.userData.policeLights;
      const on = Math.sin(elapsed * 12) > 0;
      p.red.material.color.setHex(on ? 0xff2233 : 0x330008);
      p.blue.material.color.setHex(!on ? 0x2e7bff : 0x000a33);
    }
    if (this.group.userData.underglow) {
      this.group.userData.underglow.material.opacity = 0.38 + Math.sin(elapsed * 2 + this.position.x) * 0.12;
    }
    if (this.speed > 0.2 && this.model.taillights) {
      this.model.taillights.color.setHex(0xaa1122);
    }
  }

  updateParked(dt) {
    this.speed = 0;
    this.heading = dampAngle(this.heading, this.heading, 2, dt);
  }

  updateTraffic(dt) {
    const ai = this.ai;
    if (!ai) return;
    const target = this.targetPoint;
    const dx = target.x - this.position.x, dz = target.z - this.position.z;
    const d = Math.hypot(dx, dz);
    const desiredHeading = Math.atan2(dx, dz);
    const diff = angleDiff(this.heading, desiredHeading);
    this.heading = dampAngle(this.heading, desiredHeading, 3.4, dt);
    this.steer = damp(this.steer, clamp(diff * 1.4, -1, 1), 6, dt);

    let targetSpeed = ai.cruise;
    // turn slowdown
    if (Math.abs(diff) > 0.55) targetSpeed *= 0.45;
    // obstacle ahead
    const fwd = this.forward;
    const ahead = new THREE.Vector3(this.position.x + fwd.x * 6, 0, this.position.z + fwd.z * 6);
    let block = false;
    if (this.game.player && !this.game.player.inVehicle && dist(ahead, this.game.player.position) < 3.5) block = true;
    for (const v of this.game.vehicles) {
      if (v === this || v.destroyed) continue;
      if (dist(ahead, v.position) < 3.8 && v.speed < this.speed) { block = true; break; }
    }
    if (block) targetSpeed = 0;
    this.speed = damp(this.speed, targetSpeed, block ? 8 : 2.4, dt);

    const prev = this.position.clone();
    this.position.x += Math.sin(this.heading) * this.speed * dt;
    this.position.z += Math.cos(this.heading) * this.speed * dt;
    if (this.game.city.collide(this.position, this.radius)) {
      // back off and turn
      this.position.copy(prev);
      this.heading += 1.6 * dt;
      this.speed *= 0.4;
    }
    // when near target, pick next node (avoid bouncing)
    if (d < 6.5) this.chooseNextNode();
    // keep on ground
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);

    // player collisions
    this.game.vehicleWorldCollisions(this, dt);
    this.bodyTilt = damp(this.bodyTilt, -this.steer * this.speed * 0.004, 6, dt);
  }

  updatePolice(dt) {
    const player = this.game.player;
    const target = player.inVehicle ? player.inVehicle.position : player.position;
    const dx = target.x - this.position.x, dz = target.z - this.position.z;
    const d = Math.hypot(dx, dz);
    const desiredHeading = Math.atan2(dx, dz);
    const diff = angleDiff(this.heading, desiredHeading);
    this.heading = dampAngle(this.heading, desiredHeading, 2.6, dt);
    this.steer = damp(this.steer, clamp(diff * 1.2, -1, 1), 4, dt);

    let targetSpeed = d < 8 ? 2 : d < 25 ? 15 : 25;
    this.speed = damp(this.speed, targetSpeed, 1.8, dt);
    const prev = this.position.clone();
    this.position.x += Math.sin(this.heading) * this.speed * dt;
    this.position.z += Math.cos(this.heading) * this.speed * dt;
    if (this.game.city.collide(this.position, this.radius)) {
      this.position.copy(prev);
      this.speed *= 0.3;
      this.health -= 1;
    }
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    this.game.vehicleWorldCollisions(this, dt);

    // shoot at player when close
    if (d < 32 && this.collisionCooldown <= 0) {
      this.policeFireTimer = (this.policeFireTimer ?? 1) - dt;
      if (this.policeFireTimer <= 0) {
        this.policeFireTimer = rand(0.9, 1.8);
        if (this.game.hasLineOfSight(this.position, target)) this.game.policeShoot(this, target);
      }
    }
    this.bodyTilt = damp(this.bodyTilt, -this.steer * this.speed * 0.005, 6, dt);
  }

  updatePlayer(dt) {
    const inp = this.game.input;
    const throttle = (inp.isDown('KeyW') || inp.isDown('ArrowUp')) ? 1 : 0;
    const brake = (inp.isDown('KeyS') || inp.isDown('ArrowDown')) ? 1 : 0;
    const steerInput = ((inp.isDown('KeyD') || inp.isDown('ArrowRight')) ? 1 : 0) - ((inp.isDown('KeyA') || inp.isDown('ArrowLeft')) ? 1 : 0);
    const handbrake = inp.isDown('Space');
    const boost = inp.isDown('ShiftLeft') || inp.isDown('ShiftRight');

    const maxSpeed = this.spec.maxSpeed * (boost ? 1.14 : 1) * (this.health < 30 ? 0.75 : 1);
    let accel = this.spec.accel;
    if (throttle) {
      if (this.speed < 0) { this.speed += accel * 2.2 * dt; }
      else this.speed += accel * (boost ? 1.5 : 1) * dt;
    } else if (brake) {
      if (this.speed > 0.2) this.speed -= accel * 2.4 * dt;
      else this.speed -= accel * 0.55 * dt;
    } else {
      this.speed = damp(this.speed, 0, 0.6, dt);
    }
    if (handbrake) this.speed = damp(this.speed, 0, 3.5, dt);
    this.speed = clamp(this.speed, -maxSpeed * 0.28, maxSpeed);

    const steerTarget = steerInput * (handbrake ? 1.5 : 1);
    this.steer = damp(this.steer, steerTarget, 8, dt);
    const speedFactor = clamp(Math.abs(this.speed) / 9, 0, 1);
    const turnRate = 1.55 * speedFactor * (this.speed < 0 ? -1 : 1) * (handbrake ? 1.45 : 1);
    this.heading += this.steer * turnRate * dt;

    const prev = this.position.clone();
    this.position.x += Math.sin(this.heading) * this.speed * dt;
    this.position.z += Math.cos(this.heading) * this.speed * dt;

    let collided = this.game.city.collide(this.position, this.radius);
    if (collided) {
      const moved = Math.hypot(this.position.x - prev.x, this.position.z - prev.z);
      if (moved < Math.abs(this.speed) * dt * 0.5) {
        if (this.collisionCooldown <= 0) {
          const impact = Math.abs(this.speed);
          this.health -= impact * 0.7;
          this.game.damagePlayer(impact * 0.45, this.position, 'crash');
          this.game.effects?.sparks(new THREE.Vector3((this.position.x + prev.x) / 2, this.position.y + 0.6, (this.position.z + prev.z) / 2), 12);
          this.game.audio?.crash(impact / 30);
          this.game.shake?.(clamp(impact / 40, 0, 0.6));
          this.collisionCooldown = 0.4;
        }
        this.speed *= -0.16;
      }
    }
    this.position.y = this.game.city.groundHeight(this.position.x, this.position.z);
    this.game.vehicleWorldCollisions(this, dt);
    this.bodyTilt = damp(this.bodyTilt, -this.steer * this.speed * 0.0038, 5, dt);

    if (this.health <= 0) this.explode();
    this.game.audio?.engine(this.speed, maxSpeed, this.spec.name);
  }

  damage(amount, from) {
    if (this.destroyed) return;
    this.health -= amount;
    if (this.health <= 0) this.explode();
  }

  explode() {
    if (this.destroyed) return;
    this.destroyed = true;
    this.speed = 0;
    this.game.effects?.explosion(new THREE.Vector3(this.position.x, this.position.y + 0.7, this.position.z));
    this.game.audio?.explosion();
    this.group.visible = false;
    if (this.game.player.inVehicle === this) {
      this.game.player.exitVehicle();
      this.game.player.takeDamage(35, this.position, 'explosion');
    }
    this.game.onVehicleDestroyed?.(this);
  }
}

/* ============================================================ */
export class TrafficManager {
  constructor(game, count = 22) {
    this.game = game;
    this.vehicles = [];
    this.count = count;
    this.spawnTimer = 0;
    this.spawnBatch();
  }

  randomRoadPos(minDistFromPlayer = 45) {
    for (let tries = 0; tries < 30; tries++) {
      const axis = chance(0.5) ? 'x' : 'z';
      const road = choice(CITY.roads);
      const along = rand(-215, 215);
      const x = axis === 'x' ? along : road;
      const z = axis === 'x' ? road : along;
      const p = this.game.player?.position || { x: 226, z: 142 };
      if (Math.hypot(x - p.x, z - p.z) > minDistFromPlayer) return { x, z };
    }
    return { x: rand(-180, 180), z: rand(-180, 180) };
  }

  spawnBatch() {
    for (let i = 0; i < this.count; i++) {
      const pos = this.randomRoadPos(i < 6 ? 18 : 55);
      const type = chance(0.08) ? 'taxi' : choice(TRAFFIC_TYPES);
      const v = new Vehicle(this.game, type, pos, rand(0, Math.PI * 2), chance(0.5) ? undefined : choice([0xf2e8d5, 0x2e5d8c, 0x8c3e2e, 0x2f6b3e, 0x6b4a82, 0x1f1f24]));
      v.driver = 'ai';
      v.setTrafficRoute();
      this.vehicles.push(v);
      this.game.vehicles.push(v);
    }
  }

  update(dt, elapsed) {
    for (const v of this.vehicles) {
      if (v.destroyed) continue;
      if (dist(v.position, this.game.player.position) > 260) {
        const p = this.randomRoadPos(90);
        v.position.set(p.x, 0, p.z);
        v.destroyed = false;
        v.health = 100;
        v.group.visible = true;
        v.driver = 'ai';
        v.setTrafficRoute();
      }
    }
  }
}

/* ============================================================ */
export class PoliceManager {
  constructor(game) {
    this.game = game;
    this.cars = [];
    this.spawnTimer = 0;
  }

  update(dt, wanted) {
    if (wanted <= 0) {
      for (const c of this.cars) this.game.removeVehicle(c);
      this.cars = [];
      return;
    }
    const targetCount = Math.min(5, Math.ceil(wanted * 1.3));
    this.spawnTimer -= dt;
    if (this.cars.filter(c => !c.destroyed).length < targetCount && this.spawnTimer <= 0) {
      this.spawnTimer = 2.4;
      this.spawnCar();
    }
    for (const c of this.cars) {
      if (!c.destroyed && dist(c.position, this.game.player.position) > 330) {
        c.position.set(this.game.player.position.x + rand(-80, 80), 0, this.game.player.position.z + rand(-80, 80));
        c.position.y = 0.1;
        c.heading = rand(0, Math.PI * 2);
      }
    }
    this.cars = this.cars.filter(c => !c.destroyed || c.health > -200);
  }

  spawnCar() {
    const p = this.game.player.position;
    const ang = rand(0, Math.PI * 2);
    const r = rand(80, 120);
    let x = clamp(p.x + Math.cos(ang) * r, -225, 225);
    let z = clamp(p.z + Math.sin(ang) * r, -225, 225);
    // snap to nearest road
    const nearest = CITY.roads.reduce((a, b) => Math.abs(b - x) < Math.abs(a - x) ? b : a, 0);
    if (chance(0.5)) x = nearest; else z = nearest;
    const v = new Vehicle(this.game, 'police', { x, z }, rand(0, Math.PI * 2));
    v.driver = 'police';
    v.health = 140;
    v.maxHealth = 140;
    this.cars.push(v);
    this.game.vehicles.push(v);
  }
}

import * as THREE from 'three';
import { rand, randInt, choice, glowTexture, canvasTexture, clamp } from './utils.js';

export class Effects {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.particles = [];
    this.capacity = 700;
    this.geo = new THREE.BufferGeometry();
    this.positions = new Float32Array(this.capacity * 3);
    this.colors = new Float32Array(this.capacity * 3);
    this.sizes = new Float32Array(this.capacity);
    for (let i = 0; i < this.capacity; i++) {
      this.positions[i * 3 + 1] = -1000;
      this.particles.push({ alive: false, vel: new THREE.Vector3(), life: 0, max: 0, grav: 0, drag: 1, color: new THREE.Color() });
    }
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.16, vertexColors: true, transparent: true, opacity: 0.95,
      depthWrite: false, sizeAttenuation: true, blending: THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(this.geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.cursor = 0;

    this.tracers = [];
    for (let i = 0; i < 24; i++) {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
      const mat = new THREE.LineBasicMaterial({ color: 0xfff0a0, transparent: true, opacity: 0, depthWrite: false });
      const line = new THREE.Line(geo, mat);
      line.frustumCulled = false;
      scene.add(line);
      this.tracers.push({ line, life: 0 });
    }
    this.tracerCursor = 0;

    this.flashes = [];
    const flashTex = glowTexture('#ffdc8a', 0.08);
    for (let i = 0; i < 8; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: flashTex, color: 0xffd9a0, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 }));
      s.visible = false;
      scene.add(s);
      this.flashes.push({ sprite: s, life: 0 });
    }
    this.flashCursor = 0;

    this.rings = [];
    this.pickups = [];
    this.markers = [];
    this.setupPickups();
  }

  /* ---------- particles ---------- */
  spawn(pos, vel, life, color, grav = 0, drag = 1) {
    const p = this.particles[this.cursor];
    this.cursor = (this.cursor + 1) % this.capacity;
    p.alive = true;
    p.life = life; p.max = life;
    p.vel.copy(vel);
    p.grav = grav; p.drag = drag;
    p.color.set(color);
    this.positions[p.index ?? (p.index = 0)] = 0; // noop
    const idx = (this.cursor - 1 + this.capacity) % this.capacity;
    p.i = idx;
    this.positions[idx * 3] = pos.x;
    this.positions[idx * 3 + 1] = pos.y;
    this.positions[idx * 3 + 2] = pos.z;
    this.colors[idx * 3] = p.color.r;
    this.colors[idx * 3 + 1] = p.color.g;
    this.colors[idx * 3 + 2] = p.color.b;
  }

  sparks(pos, n = 10, color = 0xffc84a) {
    for (let i = 0; i < n; i++) {
      this.spawn(pos, new THREE.Vector3(rand(-4, 4), rand(1, 6), rand(-4, 4)), rand(0.25, 0.7), color, 14, 0.94);
    }
  }

  blood(pos, n = 8) {
    for (let i = 0; i < n; i++) {
      this.spawn(new THREE.Vector3(pos.x, pos.y + 1.1, pos.z),
        new THREE.Vector3(rand(-1.8, 1.8), rand(0.4, 3.2), rand(-1.8, 1.8)),
        rand(0.3, 0.65), new THREE.Color(0.7, 0.05, 0.09), 12, 0.9);
    }
  }

  dust(pos, n = 3) {
    for (let i = 0; i < n; i++) {
      this.spawn(new THREE.Vector3(pos.x + rand(-.4, .4), pos.y + 0.08, pos.z + rand(-.4, .4)),
        new THREE.Vector3(rand(-.5, .5), rand(.2, .8), rand(-.5, .5)),
        rand(0.4, 0.9), new THREE.Color(0.55, 0.5, 0.44), -0.2, 0.92);
    }
  }

  smoke(pos, n = 10, color = 0x444444) {
    for (let i = 0; i < n; i++) {
      this.spawn(new THREE.Vector3(pos.x + rand(-1, 1), pos.y + rand(0, 1.5), pos.z + rand(-1, 1)),
        new THREE.Vector3(rand(-1.2, 1.2), rand(1, 3.5), rand(-1.2, 1.2)),
        rand(0.8, 1.8), color, -0.6, 0.92);
    }
  }

  explosion(pos) {
    this.sparks(pos, 60, 0xff9a3c);
    this.smoke(pos, 40, 0x2a2522);
    for (let i = 0; i < 20; i++) this.spawn(pos, new THREE.Vector3(rand(-6, 6), rand(2, 10), rand(-6, 6)), rand(.4, 1.1), 0xff5a1f, 10, 0.94);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 1.2, 24), new THREE.MeshBasicMaterial({ color: 0xffb45c, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.copy(pos);
    ring.position.y += 0.1;
    this.scene.add(ring);
    this.rings.push({ mesh: ring, life: 0.9, max: 0.9, kind: 'explosion' });
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture('#ffb45c', 0.1), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 1 }));
    s.position.copy(pos);
    s.scale.setScalar(4);
    this.scene.add(s);
    this.rings.push({ mesh: s, life: 0.5, max: 0.5, kind: 'flash' });
    this.game.shake?.(1.2);
  }

  tracer(from, to, color = 0xfff0a0, width = 1) {
    const t = this.tracers[this.tracerCursor];
    this.tracerCursor = (this.tracerCursor + 1) % this.tracers.length;
    const arr = t.line.geometry.attributes.position;
    arr.setXYZ(0, from.x, from.y, from.z);
    arr.setXYZ(1, to.x, to.y, to.z);
    arr.needsUpdate = true;
    t.line.material.color.setHex(color);
    t.line.material.opacity = 0.95;
    t.life = 0.08;
  }

  muzzle(pos, scale = 0.7) {
    const f = this.flashes[this.flashCursor];
    this.flashCursor = (this.flashCursor + 1) % this.flashes.length;
    f.sprite.position.copy(pos);
    f.sprite.scale.setScalar(scale);
    f.sprite.material.opacity = 1;
    f.sprite.visible = true;
    f.life = 0.06;
  }

  update(dt) {
    // particles
    for (let i = 0; i < this.capacity; i++) {
      const p = this.particles[i];
      if (!p.alive) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.alive = false;
        this.positions[i * 3 + 1] = -1000;
        continue;
      }
      const idx = p.i;
      p.vel.y -= p.grav * dt;
      p.vel.multiplyScalar(Math.pow(p.drag, dt * 60));
      this.positions[idx * 3] += p.vel.x * dt;
      this.positions[idx * 3 + 1] += p.vel.y * dt;
      this.positions[idx * 3 + 2] += p.vel.z * dt;
      const fade = clamp(p.life / p.max, 0, 1);
      this.colors[idx * 3] = p.color.r * fade;
      this.colors[idx * 3 + 1] = p.color.g * fade;
      this.colors[idx * 3 + 2] = p.color.b * fade;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    for (const t of this.tracers) {
      if (t.life > 0) {
        t.life -= dt;
        t.line.material.opacity = Math.max(0, t.life / 0.08) * 0.9;
      } else t.line.material.opacity = 0;
    }
    for (const f of this.flashes) {
      if (f.life > 0) {
        f.life -= dt;
        f.sprite.material.opacity = Math.max(0, f.life / 0.06);
        if (f.life <= 0) f.sprite.visible = false;
      }
    }
    for (const r of this.rings) {
      r.life -= dt;
      const k = 1 - Math.max(0, r.life) / r.max;
      if (r.kind === 'explosion') {
        r.mesh.scale.setScalar(1 + k * 8);
        r.mesh.material.opacity = (1 - k) * 0.9;
      } else {
        r.mesh.scale.setScalar(4 + k * 18);
        r.mesh.material.opacity = (1 - k);
      }
      if (r.life <= 0) this.scene.remove(r.mesh);
    }
    this.rings = this.rings.filter(r => r.life > 0);

    // pickups / markers
    for (const p of this.pickups) p.update?.(dt, this.game);
    for (const m of this.markers) m.update?.(dt, this.game);
  }

  /* ---------- pickups ---------- */
  setupPickups() {
    const spots = [
      { x: 222, z: 132, type: 'health' },
      { x: 222, z: 118, type: 'armor' },
      { x: 208, z: 12, type: 'ammo' },
      { x: 12, z: 208, type: 'health' },
      { x: -108, z: -8, type: 'armor' },
      { x: -8, z: -108, type: 'ammo' },
      { x: 108, z: 108, type: 'cash' },
      { x: -208, z: 108, type: 'health' },
      { x: -108, z: 208, type: 'ammo' },
      { x: 108, z: -208, type: 'armor' },
      { x: 208, z: 100, type: 'cash' },
      { x: 8, z: -8, type: 'health' },
    ];
    for (const s of spots) this.addPickup(s);
  }

  addPickup({ x, z, type }) {
    const group = new THREE.Group();
    const y = this.game.city.groundHeight(x, z) + 1.1;
    group.position.set(x, y, z);
    const color = type === 'health' ? 0x38ef7d : type === 'armor' ? 0x40c4ff : type === 'ammo' ? 0xffd15c : 0x7dff8e;
    let icon;
    if (type === 'health') {
      icon = new THREE.Group();
      const m = new THREE.MeshBasicMaterial({ color, toneMapped: false });
      const a = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.22, 0.16), m);
      const b = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.66, 0.16), m);
      icon.add(a, b);
    } else if (type === 'armor') {
      icon = new THREE.Mesh(new THREE.OctahedronGeometry(0.42), new THREE.MeshBasicMaterial({ color, toneMapped: false, wireframe: false }));
    } else if (type === 'ammo') {
      icon = new THREE.Group();
      const m = new THREE.MeshBasicMaterial({ color, toneMapped: false });
      const box = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.46, 0.3), m);
      icon.add(box);
    } else {
      const tex = canvasTexture(128, 64, (ctx, w, h) => {
        ctx.fillStyle = '#0b3d16'; ctx.fillRect(0, 0, w, h);
        ctx.fillStyle = color; ctx.font = 'bold 50px "Courier New"'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText('$', w / 2, h / 2 + 3);
      });
      icon = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.42, 0.12), new THREE.MeshBasicMaterial({ map: tex, toneMapped: false }));
    }
    group.add(icon);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.55, 0.75, 24), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = -0.95;
    group.add(ring);
    const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 5, 12, 1, true), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.08, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    beam.position.y = 1.4;
    group.add(beam);
    this.scene.add(group);
    const p = {
      group, type, active: true, respawn: 0, base: group.position.clone(), t: rand(0, 6),
      update: (dt, game) => {
        p.t += dt;
        if (!p.active) {
          p.respawn -= dt;
          if (p.respawn <= 0) { p.active = true; group.visible = true; }
          return;
        }
        group.position.y = p.base.y + Math.sin(p.t * 2) * 0.16;
        icon.rotation.y += dt * 1.8;
        group.children[0].rotation.y = p.t * 1.8;
        group.rotation.y = 0;
        const pp = game.player.position;
        if (Math.hypot(pp.x - group.position.x, pp.z - group.position.z) < 2.2 && Math.abs(pp.y - group.position.y) < 4) {
          p.active = false;
          p.respawn = 35;
          group.visible = false;
          game.collectPickup(type);
        }
      },
    };
    this.pickups.push(p);
  }

  /* ---------- world markers ---------- */
  addMarker(pos, { color = 0xff2d95, label = 'M', radius = 2.2, beam = true } = {}) {
    const group = new THREE.Group();
    const y = this.game.city.groundHeight(pos.x, pos.z);
    group.position.set(pos.x, y + 0.06, pos.z);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(radius, 0.09, 8, 40), new THREE.MeshBasicMaterial({ color, toneMapped: false, transparent: true, opacity: 0.9 }));
    ring.rotation.x = -Math.PI / 2;
    group.add(ring);
    const inner = new THREE.Mesh(new THREE.CircleGeometry(radius * 0.9, 32), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.15, side: THREE.DoubleSide, depthWrite: false }));
    inner.rotation.x = -Math.PI / 2;
    group.add(inner);
    if (beam) {
      const b = new THREE.Mesh(new THREE.CylinderGeometry(0.35, radius * 0.9, 15, 16, 1, true), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.11, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
      b.position.y = 7.5;
      group.add(b);
    }
    // label sprite
    const tex = canvasTexture(128, 128, (ctx, w, h) => {
      ctx.fillStyle = 'rgba(0,0,0,0)'; ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 5; ctx.beginPath(); ctx.arc(64, 64, 42, 0, Math.PI * 2); ctx.stroke();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 58px "Arial Black"'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(label, 64, 68);
    });
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, color, transparent: true, depthWrite: false, toneMapped: false }));
    sprite.scale.setScalar(1.5);
    sprite.position.y = 3.2;
    group.add(sprite);
    this.scene.add(group);
    const m = {
      group, pos: new THREE.Vector3(pos.x, y, pos.z), radius, color, active: true, t: 0,
      setVisible(v) { group.visible = v; m.active = v; },
      setPosition(p) { m.pos.set(p.x, this.game.city.groundHeight(p.x, p.z), p.z); group.position.set(p.x, m.pos.y + 0.06, p.z); },
      dispose() { this.scene.remove(group); group.traverse(o => { if (o.geometry) o.geometry.dispose?.(); }); m.disposed = true; },
      update(dt) {
        m.t += dt;
        ring.rotation.z += dt * 0.7;
        const s = 1 + Math.sin(m.t * 3) * 0.05;
        group.scale.set(s, 1, s);
        sprite.position.y = 3.2 + Math.sin(m.t * 2) * 0.12;
      },
    };
    this.markers.push(m);
    return m;
  }
}

import { CITY, clamp, formatMoney, formatTime } from './utils.js';

const STAR = `<svg class="star" viewBox="0 0 24 24"><path d="M12 1.6l3.1 6.6 7.1 1-5.2 5.1 1.3 7.2L12 18l-6.3 3.5 1.3-7.2L1.8 9.2l7.1-1z" fill="#ffcf3f" stroke="#7a4b00" stroke-width="1"/></svg>`;

export class HUD {
  constructor(game) {
    this.game = game;
    this.el = {};
    const ids = [
      'minimap', 'bigmap', 'health-fill', 'health-num', 'armor-fill', 'armor-num', 'money', 'time',
      'wanted', 'objective-text', 'objective-kicker', 'objective-timer', 'objective', 'mission-name',
      'toasts', 'prompt', 'prompt-text', 'banner', 'banner-kicker', 'banner-title', 'banner-sub', 'subtitle',
      'weapon-panel', 'weapon-name', 'ammo-mag', 'ammo-reserve', 'vehicle-hud', 'speed', 'sp-fill', 'car-name',
      'radio', 'track', 'damage-flash', 'crosshair', 'district', 'help', 'pause-screen', 'pause-sub',
      'p-missions', 'p-money', 'p-wanted', 'map-screen', 'death-screen', 'death-loss', 'mission-screen',
      'ms-kicker', 'ms-title', 'ms-sub', 'health-row', 'ammo-mag',
    ];
    for (const id of ids) this.el[id] = document.getElementById(id);
    this.mm = this.el.minimap.getContext('2d');
    this.big = this.el.bigmap.getContext('2d');
    this.el.wanted.innerHTML = Array(5).fill(STAR).join('');
    this.stars = [...this.el.wanted.querySelectorAll('.star')];
    this.lastWanted = -1;
    this.lastObjective = '';
    this.objectiveUrgent = false;
    this.mmTimer = 0;
    this.bigTimer = 0;
    this.dmgTimer = 0;
    this.promptVisible = false;
    this.bannerTimer = 0;
    this.districtTimer = 0;
    this.radioIndex = 0;
    this.radioTimer = 0;
    this.tracks = ['MIDNIGHT DRIVE', 'NEON HEART', 'OCEAN DRIVE', 'PALM SHADOWS', 'AFTERGLOW', 'VICE NIGHTS'];
    this.el.track.textContent = this.tracks[0];
  }

  update(dt) {
    const g = this.game;
    const p = g.player;
    if (!p) return;

    this.el['health-fill'].style.width = `${clamp(p.health, 0, 100)}%`;
    this.el['health-num'].textContent = Math.ceil(p.health);
    this.el['health-row'].classList.toggle('critical', p.health < 30);
    this.el['armor-fill'].style.width = `${clamp(p.armor, 0, 100)}%`;
    this.el['armor-num'].textContent = Math.ceil(p.armor);
    this.el.money.textContent = formatMoney(g.money);
    this.el.time.textContent = g.clockString();

    if (g.wanted !== this.lastWanted) {
      this.lastWanted = g.wanted;
      this.stars.forEach((s, i) => s.classList.toggle('on', i < g.wanted));
    }

    // weapons / vehicle hud
    if (p.inVehicle) {
      document.body.classList.add('driving');
      this.el['weapon-panel'].classList.add('hidden');
      this.el['vehicle-hud'].classList.remove('hidden');
      const kmh = Math.round(Math.abs(p.inVehicle.speed) * 3.6);
      this.el.speed.textContent = kmh;
      const ratio = clamp(Math.abs(p.inVehicle.speed) / (p.inVehicle.spec.maxSpeed * 1.1), 0, 1);
      this.el['sp-fill'].style.strokeDasharray = `${ratio * 245} 327`;
      this.el['car-name'].textContent = p.inVehicle.name;
      if (p.inVehicle.destroyed) this.el['car-name'].textContent = 'WRECKED';
      this.radioTimer += dt;
      if (this.radioTimer > 24) {
        this.radioTimer = 0;
        this.radioIndex = (this.radioIndex + 1) % this.tracks.length;
        this.el.track.textContent = this.tracks[this.radioIndex];
      }
    } else {
      document.body.classList.remove('driving');
      this.el['weapon-panel'].classList.remove('hidden');
      this.el['vehicle-hud'].classList.add('hidden');
      this.el['weapon-name'].textContent = p.reloading > 0 ? 'RELOADING' : p.weapon.name;
      this.el['ammo-mag'].textContent = p.weapon.mag;
      this.el['ammo-reserve'].textContent = p.weapon.reserve;
      this.el['ammo-mag'].parentElement.classList.toggle('low', p.weapon.mag <= 3);
    }

    this.dmgTimer = Math.max(0, this.dmgTimer - dt);
    this.el['damage-flash'].style.opacity = this.dmgTimer > 0 ? Math.min(0.85, this.dmgTimer * 2.6) : 0;

    this.districtTimer -= dt;
    if (this.districtTimer <= 0) {
      this.districtTimer = 0.4;
      this.el.district.textContent = g.city.districtAt(p.position.x, p.position.z);
    }

    this.mmTimer -= dt;
    if (this.mmTimer <= 0) {
      this.mmTimer = 0.06;
      this.drawMinimap();
    }
    if (!this.el['map-screen'].classList.contains('hidden')) {
      this.bigTimer -= dt;
      if (this.bigTimer <= 0) { this.bigTimer = 0.2; this.drawBigMap(); }
    }

    if (this.bannerTimer > 0) {
      this.bannerTimer -= dt;
      if (this.bannerTimer <= 0) this.el.banner.classList.add('hidden');
    }
  }

  setObjective(text, kicker = 'VICE BEACH', timer = '') {
    if (text !== this.lastObjective) {
      this.lastObjective = text;
      this.el['objective-text'].textContent = text;
      this.el.objective.style.opacity = 1;
    }
    this.el['objective-kicker'].textContent = kicker;
    this.el['objective-timer'].textContent = timer;
    this.el.objective.classList.toggle('urgent', Boolean(timer) && !timer.includes('—'));
  }

  setMissionName(name) { this.el['mission-name'].textContent = name; }

  toast(text, type = '') {
    const d = document.createElement('div');
    d.className = 'toast ' + type;
    d.textContent = text;
    this.el.toasts.appendChild(d);
    setTimeout(() => d.remove(), 3200);
    if (this.el.toasts.children.length > 4) this.el.toasts.firstChild.remove();
  }

  showBanner(kicker, title, sub = '', duration = 3.4) {
    this.el['banner-kicker'].textContent = kicker;
    this.el['banner-title'].textContent = title;
    this.el['banner-sub'].textContent = sub;
    this.el.banner.classList.remove('hidden');
    this.el.banner.style.animation = 'none';
    void this.el.banner.offsetWidth;
    this.el.banner.style.animation = '';
    this.bannerTimer = duration;
  }

  subtitle(text, duration = 3) {
    this.el.subtitle.textContent = text;
    this.el.subtitle.classList.add('on');
    clearTimeout(this._subT);
    this._subT = setTimeout(() => this.el.subtitle.classList.remove('on'), duration * 1000);
  }

  setPrompt(text) {
    if (!text) {
      this.el.prompt.classList.add('hidden');
      this.promptVisible = false;
      return;
    }
    if (this.promptVisible && this.el['prompt-text'].textContent === text) return;
    this.el['prompt-text'].textContent = text;
    this.el.prompt.classList.remove('hidden');
    this.promptVisible = true;
  }

  damage() {
    this.dmgTimer = 0.35;
    this.el['damage-flash'].style.opacity = 0.7;
  }

  hitMarker() {
    this.el.crosshair.classList.add('hit');
    clearTimeout(this._hitT);
    this._hitT = setTimeout(() => this.el.crosshair.classList.remove('hit'), 120);
  }

  toggleHelp(force) {
    const show = force ?? this.el.help.classList.contains('hidden');
    this.el.help.classList.toggle('hidden', !show);
    return show;
  }

  toggleMap() {
    const show = this.el['map-screen'].classList.contains('hidden');
    this.el['map-screen'].classList.toggle('hidden', !show);
    if (show) this.drawBigMap();
    return show;
  }

  closeMap() { this.el['map-screen'].classList.add('hidden'); }

  showPause(show, missionsDone = 0) {
    this.el['pause-screen'].classList.toggle('hidden', !show);
    if (show) {
      this.el['p-missions'].textContent = `${missionsDone} / 5`;
      this.el['p-money'].textContent = formatMoney(this.game.money);
      this.el['p-wanted'].textContent = this.game.wanted > 0 ? '★'.repeat(this.game.wanted) : 'CLEAN';
    }
  }

  showMissionComplete(title, reward, callback) {
    const s = this.el['mission-screen'];
    this.el['ms-kicker'].textContent = 'MISSION COMPLETE';
    this.el['ms-title'].textContent = title;
    this.el['ms-sub'].textContent = `Reward: ${formatMoney(reward)}`;
    s.classList.remove('hidden');
    setTimeout(() => {
      s.classList.add('hidden');
      callback?.();
    }, 3600);
  }

  showDeath(loss, callback) {
    const s = this.el['death-screen'];
    this.el['death-loss'].textContent = formatMoney(loss);
    s.classList.remove('hidden');
    setTimeout(() => {
      s.classList.add('hidden');
      callback?.();
    }, 3400);
  }

  /* ---------------- minimap ---------------- */
  drawMapBase(ctx, w, h, scale, cx, cz, detailed = false) {
    const s = scale;
    ctx.save();
    ctx.translate(w / 2, h / 2);
    ctx.scale(s, s);
    ctx.translate(-cx, -cz);
    // water
    ctx.fillStyle = '#082832';
    ctx.fillRect(cx - w / 2 / s - 50, cz - h / 2 / s - 50, w / s + 100, h / s + 100);
    // land
    ctx.fillStyle = '#25302d';
    ctx.fillRect(-243, -243, 486, 486);
    // beach
    ctx.fillStyle = '#7a6646';
    ctx.fillRect(243, -243, 70, 486);
    // pier
    ctx.fillStyle = '#6b5138';
    ctx.fillRect(302, 56, 80, 16);
    // blocks (sidewalk)
    ctx.fillStyle = '#33403b';
    for (const b of this.game.city.blocks) ctx.fillRect(b.cx - 42, b.cz - 42, 84, 84);
    // special zones
    ctx.fillStyle = '#2f5a3b';
    ctx.fillRect(50 - 35, -150 - 35, 70, 70);
    // roads
    ctx.strokeStyle = '#6d716e';
    ctx.lineWidth = 18;
    ctx.lineCap = 'butt';
    for (const r of CITY.roads) {
      ctx.beginPath(); ctx.moveTo(r, -243); ctx.lineTo(r, 243); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-243, r); ctx.lineTo(243, r); ctx.stroke();
    }
    // center lines
    if (detailed) {
      ctx.strokeStyle = 'rgba(230,226,207,0.55)';
      ctx.lineWidth = 0.55;
      ctx.setLineDash([4, 6]);
      for (const r of CITY.roads) {
        ctx.beginPath(); ctx.moveTo(r, -243); ctx.lineTo(r, 243); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-243, r); ctx.lineTo(243, r); ctx.stroke();
      }
      ctx.setLineDash([]);
    }
    // buildings (from colliders for footprint)
    if (detailed) {
      ctx.fillStyle = '#1b2320';
      for (const c of this.game.city.colliders) {
        ctx.fillRect(c.minX, c.minZ, c.maxX - c.minX, c.maxZ - c.minZ);
      }
    }
    // label districts
    if (detailed) {
      ctx.save();
      ctx.scale(1 / s, 1 / s);
      ctx.fillStyle = 'rgba(255,255,255,0.22)';
      ctx.font = 'bold 10px Rajdhani, sans-serif';
      ctx.textAlign = 'center';
      const labels = [['OCEAN BEACH', 210, 0], ['DOWNTOWN', -50, -50], ['VICE DOCKS', -150, -150], ['VICE POINT', 340, 64], ['NORTH POINT', 0, -215], ['SOUTH BEACH', 0, 215], ['WEST HEIGHTS', -205, 0]];
      for (const [t, x, z] of labels) ctx.fillText(t, x * s, z * s);
      ctx.restore();
    }
    ctx.restore();
  }

  drawPoints(ctx, w, h, scale, cx, cz, detailed = false) {
    const g = this.game;
    const s = scale;
    const toScreen = (x, z) => [w / 2 + (x - cx) * s, h / 2 + (z - cz) * s];
    // vehicles
    for (const v of g.vehicles) {
      if (v.destroyed) continue;
      const [x, y] = toScreen(v.position.x, v.position.z);
      if (x < -10 || y < -10 || x > w + 10 || y > h + 10) continue;
      if (v.driver === 'police') {
        ctx.fillStyle = '#2f7bff';
        ctx.beginPath(); ctx.arc(x, y, detailed ? 3.4 : 2.8, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = 'rgba(47,123,255,0.35)'; ctx.lineWidth = 2; ctx.stroke();
      } else {
        ctx.fillStyle = 'rgba(224,224,214,0.65)';
        ctx.beginPath(); ctx.arc(x, y, detailed ? 2.2 : 1.7, 0, Math.PI * 2); ctx.fill();
      }
    }
    // enemies
    for (const e of g.enemies) {
      if (e.dead) continue;
      const [x, y] = toScreen(e.position.x, e.position.z);
      ctx.fillStyle = '#ff3b4e';
      ctx.beginPath(); ctx.arc(x, y, detailed ? 3.4 : 2.6, 0, Math.PI * 2); ctx.fill();
    }
    // mission marker
    const mm = g.missions;
    if (mm?.startMarker?.active) {
      const [x, y] = toScreen(mm.startMarker.pos.x, mm.startMarker.pos.z);
      this.drawMarkerDot(ctx, x, y, '#ff2d95', 'M', detailed);
    }
    if (mm?.objectiveMarker?.active) {
      const [x, y] = toScreen(mm.objectiveMarker.pos.x, mm.objectiveMarker.pos.z);
      this.drawMarkerDot(ctx, x, y, '#ffd15c', '!', detailed);
    }
    if (mm?.briefcaseMarker?.active) {
      const [x, y] = toScreen(mm.briefcaseMarker.pos.x, mm.briefcaseMarker.pos.z);
      this.drawMarkerDot(ctx, x, y, '#7dff8e', '$', detailed);
    }
    // player
    const p = g.player;
    const [px, py] = toScreen(p.position.x, p.position.z);
    ctx.save();
    ctx.translate(px, py);
    const hdg = p.inVehicle ? p.inVehicle.heading : p.heading;
    ctx.rotate(Math.PI - hdg);
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(6, 6); ctx.lineTo(0, 3); ctx.lineTo(-6, 6); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.6)'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.restore();
  }

  drawMarkerDot(ctx, x, y, color, label, detailed) {
    const r = detailed ? 10 : 7;
    ctx.save();
    ctx.shadowColor = color; ctx.shadowBlur = 14;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    ctx.fillStyle = '#140a20';
    ctx.font = `bold ${detailed ? 12 : 9}px "Arial Black", sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(label, x, y + 0.5);
  }

  drawMinimap() {
    const ctx = this.mm;
    const w = 420, h = 420;
    const p = this.game.player;
    const scale = 1.75;
    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.beginPath();
    ctx.arc(w / 2, h / 2, w / 2 - 2, 0, Math.PI * 2);
    ctx.clip();
    this.drawMapBase(ctx, w, h, scale, p.position.x, p.position.z);
    this.drawPoints(ctx, w, h, scale, p.position.x, p.position.z);
    // edge fade
    const grad = ctx.createRadialGradient(w / 2, h / 2, w * 0.34, w / 2, h / 2, w * 0.5);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(4,8,12,0.55)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }

  drawBigMap() {
    const ctx = this.big;
    const w = 900, h = 900;
    const p = this.game.player;
    const scale = 900 / 520;
    ctx.clearRect(0, 0, w, h);
    this.drawMapBase(ctx, w, h, scale, 0, 0, true);
    this.drawPoints(ctx, w, h, scale, 0, 0, true);
    // frame
    ctx.strokeStyle = 'rgba(255,255,255,.14)'; ctx.lineWidth = 3;
    ctx.strokeRect(1.5, 1.5, w - 3, h - 3);
    // scale bar
    ctx.fillStyle = 'rgba(255,255,255,.35)';
    ctx.font = '16px "Share Tech Mono", monospace';
    ctx.fillText('0        100m', 30, h - 26);
    ctx.fillRect(30, h - 40, 100 * scale / 2, 3);
  }
}

import { clamp, rand } from './utils.js';

const CHORDS = [
  [45, 48, 52, 57], // Am
  [41, 45, 48, 53], // F
  [48, 52, 55, 60], // C
  [43, 47, 50, 55], // G
];
const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.enabled = true;
    this.musicOn = true;
    this.nextStep = 0;
    this.stepIndex = 0;
    this.lastSchedule = 0;
    this.engine = null;
    this.siren = null;
    this.engineTarget = 0;
    this.sirenLevel = 0;
    this.noiseBuffer = null;
    this.started = false;
  }

  start() {
    if (this.ctx) { this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) { this.enabled = false; return; }
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.9;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.16;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.55;
    this.sfxGain.connect(this.master);

    // noise buffer
    const len = this.ctx.sampleRate * 1.2;
    this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    this.startEngine();
    this.startSiren();
    this.nextStep = this.ctx.currentTime + 0.2;
    this.started = true;
  }

  /* ---------- music ---------- */
  scheduleMusic() {
    if (!this.ctx || !this.musicOn) return;
    const ahead = 0.25;
    while (this.nextStep < this.ctx.currentTime + ahead) {
      this.playStep(this.stepIndex, this.nextStep);
      this.nextStep += 0.3125; // 96 BPM eighth notes
      this.stepIndex = (this.stepIndex + 1) % 32;
    }
  }

  playStep(step, time) {
    const bar = Math.floor(step / 8) % 4;
    const inBar = step % 8;
    const chord = CHORDS[bar];

    // pad (start of each bar)
    if (inBar === 0) {
      for (const n of chord) {
        this.pad(midi(n + 12), time, 2.35, 0.05);
      }
      this.pad(midi(chord[0] + 24), time, 2.4, 0.022);
    }
    // bass
    if (inBar === 0 || inBar === 3 || inBar === 6) {
      this.bass(midi(chord[0] - 12), time, inBar === 0 ? 0.6 : 0.35, 0.12);
    }
    // arp
    const arpNotes = [chord[0] + 12, chord[1] + 12, chord[2] + 12, chord[3] + 12];
    const n = arpNotes[(step * 3) % 4];
    this.arp(midi(n + 12), time, inBar % 2 === 0 ? 0.055 : 0.03);
    // drums
    if (inBar === 0 || inBar === 4) this.kick(time);
    if (inBar === 2 || inBar === 6) this.snare(time);
    if (inBar % 2 === 1) this.hat(time, 0.028);
  }

  pad(freq, time, dur, vol) {
    const c = this.ctx;
    const g = c.createGain();
    g.gain.setValueAtTime(0, time);
    g.gain.linearRampToValueAtTime(vol, time + 0.35);
    g.gain.linearRampToValueAtTime(0, time + dur);
    const f = c.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 1200; f.Q.value = 0.6;
    const o1 = c.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = freq;
    const o2 = c.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = freq * 1.006;
    o1.connect(f); o2.connect(f); f.connect(g); g.connect(this.musicGain);
    o1.start(time); o2.start(time); o1.stop(time + dur + 0.05); o2.stop(time + dur + 0.05);
  }

  bass(freq, time, dur, vol) {
    const c = this.ctx;
    const g = c.createGain();
    g.gain.setValueAtTime(0, time);
    g.gain.linearRampToValueAtTime(vol, time + 0.02);
    g.gain.exponentialRampToValueAtTime(0.001, time + dur);
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 420; f.Q.value = 4;
    const o = c.createOscillator(); o.type = 'sawtooth'; o.frequency.value = freq;
    o.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(time); o.stop(time + dur + 0.02);
  }

  arp(freq, time, vol) {
    const c = this.ctx;
    const g = c.createGain();
    g.gain.setValueAtTime(0, time);
    g.gain.linearRampToValueAtTime(vol, time + 0.01);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.28);
    const o = c.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
    const d = c.createDelay(); d.delayTime.value = 0.3125;
    const dg = c.createGain(); dg.gain.value = 0.32;
    o.connect(g); g.connect(this.musicGain);
    g.connect(d); d.connect(dg); dg.connect(this.musicGain);
    o.start(time); o.stop(time + 0.3);
  }

  kick(time) {
    const c = this.ctx;
    const o = c.createOscillator(); o.type = 'sine';
    const g = c.createGain();
    o.frequency.setValueAtTime(140, time);
    o.frequency.exponentialRampToValueAtTime(38, time + 0.13);
    g.gain.setValueAtTime(0.26, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.28);
    o.connect(g); g.connect(this.musicGain);
    o.start(time); o.stop(time + 0.3);
  }

  snare(time) {
    const c = this.ctx;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1900; f.Q.value = 0.8;
    const g = c.createGain();
    g.gain.setValueAtTime(0.13, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.17);
    s.connect(f); f.connect(g); g.connect(this.musicGain);
    s.start(time); s.stop(time + 0.2);
    const o = c.createOscillator(); o.type = 'triangle'; o.frequency.value = 180;
    const og = c.createGain(); og.gain.setValueAtTime(0.05, time); og.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
    o.connect(og); og.connect(this.musicGain); o.start(time); o.stop(time + 0.12);
  }

  hat(time, vol) {
    const c = this.ctx;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 7500;
    const g = c.createGain();
    g.gain.setValueAtTime(vol, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.05);
    s.connect(f); f.connect(g); g.connect(this.musicGain);
    s.start(time); s.stop(time + 0.06);
  }

  /* ---------- loops ---------- */
  startEngine() {
    const c = this.ctx;
    const o1 = c.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 60;
    const o2 = c.createOscillator(); o2.type = 'square'; o2.frequency.value = 30;
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 300; f.Q.value = 2;
    const g = c.createGain(); g.gain.value = 0;
    o1.connect(f); o2.connect(f); f.connect(g); g.connect(this.sfxGain);
    o1.start(); o2.start();
    this.engine = { o1, o2, f, g };
  }

  startSiren() {
    const c = this.ctx;
    const o = c.createOscillator(); o.type = 'square'; o.frequency.value = 700;
    const f = c.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 2;
    const g = c.createGain(); g.gain.value = 0;
    o.connect(f); f.connect(g); g.connect(this.sfxGain);
    o.start();
    this.siren = { o, g };
  }

  updateLoop(game, dt) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const p = game.player;
    let target = 0, freq = 50;
    if (p?.inVehicle && !p.inVehicle.destroyed) {
      const ratio = clamp(Math.abs(p.inVehicle.speed) / p.inVehicle.spec.maxSpeed, 0, 1.2);
      target = 0.035 + ratio * 0.075;
      freq = 46 + ratio * 165;
    }
    this.engineTarget += (target - this.engineTarget) * Math.min(1, dt * 8);
    this.engine.g.gain.setTargetAtTime(this.engineTarget, now, 0.08);
    this.engine.o1.frequency.setTargetAtTime(freq, now, 0.1);
    this.engine.o2.frequency.setTargetAtTime(freq * 0.5, now, 0.1);
    this.engine.f.frequency.setTargetAtTime(240 + freq * 2.2, now, 0.1);

    // siren
    let nearest = 999;
    for (const v of game.vehicles) {
      if (v.driver === 'police' && !v.destroyed) {
        nearest = Math.min(nearest, Math.hypot(v.position.x - p.position.x, v.position.z - p.position.z));
      }
    }
    const sTarget = game.wanted > 0 && nearest < 110 ? clamp(1 - nearest / 110, 0, 1) * 0.045 : 0;
    this.sirenLevel += (sTarget - this.sirenLevel) * Math.min(1, dt * 4);
    this.siren.g.gain.setTargetAtTime(this.sirenLevel, now, 0.1);
    this.siren.o.frequency.setTargetAtTime(Math.sin(now * 3.2) > 0 ? 820 : 560, now, 0.02);
  }

  /* ---------- sfx ---------- */
  gunshot(kind = 'pistol') {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'lowpass';
    f.frequency.setValueAtTime(kind === 'smg' ? 3400 : 2600, t);
    f.frequency.exponentialRampToValueAtTime(300, t + 0.12);
    const g = c.createGain();
    g.gain.setValueAtTime(kind === 'smg' ? 0.3 : 0.42, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    s.connect(f); f.connect(g); g.connect(this.sfxGain);
    s.start(t); s.stop(t + 0.2);
    const o = c.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(40, t + 0.1);
    const og = c.createGain(); og.gain.setValueAtTime(0.22, t); og.gain.exponentialRampToValueAtTime(0.001, t + 0.14);
    o.connect(og); og.connect(this.sfxGain); o.start(t); o.stop(t + 0.15);
  }

  reload() {
    if (!this.ctx) return;
    const c = this.ctx;
    for (let i = 0; i < 2; i++) {
      const t = c.currentTime + i * 0.17;
      const o = c.createOscillator(); o.type = 'square'; o.frequency.value = i ? 420 : 300;
      const g = c.createGain(); g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
      o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.07);
    }
  }

  impact() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 900;
    const g = c.createGain(); g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    s.connect(f); f.connect(g); g.connect(this.sfxGain); s.start(t); s.stop(t + 0.1);
  }

  explosion() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(900, t); f.frequency.exponentialRampToValueAtTime(90, t + 0.8);
    const g = c.createGain(); g.gain.setValueAtTime(0.7, t); g.gain.exponentialRampToValueAtTime(0.001, t + 1.1);
    s.connect(f); f.connect(g); g.connect(this.sfxGain); s.start(t); s.stop(t + 1.15);
    const o = c.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(90, t); o.frequency.exponentialRampToValueAtTime(25, t + 0.5);
    const og = c.createGain(); og.gain.setValueAtTime(0.5, t); og.gain.exponentialRampToValueAtTime(0.001, t + 0.7);
    o.connect(og); og.connect(this.sfxGain); o.start(t); o.stop(t + 0.75);
  }

  crash(power = 0.5) {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const s = c.createBufferSource(); s.buffer = this.noiseBuffer;
    const f = c.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 380;
    const g = c.createGain(); g.gain.setValueAtTime(clamp(power, 0.05, 0.4), t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
    s.connect(f); f.connect(g); g.connect(this.sfxGain); s.start(t); s.stop(t + 0.25);
  }

  hurt() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const o = c.createOscillator(); o.type = 'sawtooth'; o.frequency.setValueAtTime(220, t); o.frequency.exponentialRampToValueAtTime(90, t + 0.2);
    const g = c.createGain(); g.gain.setValueAtTime(0.08, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
    o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.24);
  }

  pickup(kind = 'health') {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const notes = kind === 'cash' ? [880, 1174, 1568] : [660, 880, 1320];
    notes.forEach((freq, i) => {
      const o = c.createOscillator(); o.type = 'sine'; o.frequency.value = freq;
      const g = c.createGain();
      g.gain.setValueAtTime(0, t + i * 0.07);
      g.gain.linearRampToValueAtTime(0.09, t + i * 0.07 + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.07 + 0.18);
      o.connect(g); g.connect(this.sfxGain); o.start(t + i * 0.07); o.stop(t + i * 0.07 + 0.2);
    });
  }

  cash() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    [1200, 1600, 2000].forEach((freq, i) => {
      const o = c.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
      const g = c.createGain(); g.gain.setValueAtTime(0.05, t + i * 0.05); g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.05 + 0.12);
      o.connect(g); g.connect(this.sfxGain); o.start(t + i * 0.05); o.stop(t + i * 0.05 + 0.14);
    });
  }

  mission() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    [220, 277, 330, 440].forEach((freq, i) => {
      const o = c.createOscillator(); o.type = 'sawtooth'; o.frequency.value = freq;
      const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 2200;
      const g = c.createGain();
      g.gain.setValueAtTime(0, t + i * 0.1); g.gain.linearRampToValueAtTime(0.07, t + i * 0.1 + 0.03); g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.1 + 0.6);
      o.connect(f); f.connect(g); g.connect(this.sfxGain); o.start(t + i * 0.1); o.stop(t + i * 0.1 + 0.65);
    });
  }

  fail() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    [330, 262, 196].forEach((freq, i) => {
      const o = c.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
      const g = c.createGain(); g.gain.setValueAtTime(0.08, t + i * 0.15); g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.15 + 0.4);
      o.connect(g); g.connect(this.sfxGain); o.start(t + i * 0.15); o.stop(t + i * 0.15 + 0.45);
    });
  }

  wanted() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const o = c.createOscillator(); o.type = 'square'; o.frequency.setValueAtTime(440, t); o.frequency.setValueAtTime(660, t + 0.12);
    const g = c.createGain(); g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
    o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.3);
  }

  jump() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const o = c.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(280, t); o.frequency.exponentialRampToValueAtTime(620, t + 0.1);
    const g = c.createGain(); g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.13);
  }

  ui() {
    if (!this.ctx) return;
    const c = this.ctx, t = c.currentTime;
    const o = c.createOscillator(); o.type = 'sine'; o.frequency.value = 900;
    const g = c.createGain(); g.gain.setValueAtTime(0.03, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
    o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 0.06);
  }

  update(game, dt) {
    if (!this.ctx) return;
    this.scheduleMusic();
    this.updateLoop(game, dt);
  }
}

